let lang=document.body.dataset.locale||'en',page='dashboard',newJobStep=1,jobTab='flex',taxTab='rates',tableQuery='',settingsTab='Business';
const workspaceName=document.body.dataset.workspace||'PressFlow';
const $=(sel,root=document)=>root.querySelector(sel);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(s)=>labels[lang]?.[s]||s;
const money=n=>(dashboardSummary?.currency||'LKR')+' '+Number(n||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function apiRequest(url,options={}){
 const {method='GET',headers:customHeaders={},...rest}=options;
 const headers={Accept:'application/json','X-Requested-With':'XMLHttpRequest',...customHeaders};
 if(!['GET','HEAD'].includes(method.toUpperCase())){
  headers['Content-Type']=headers['Content-Type']||'application/json';
  headers['X-CSRF-TOKEN']=$('meta[name="csrf-token"]')?.content||'';
 }
 const response=await fetch(url,{...rest,method,headers,credentials:'same-origin'});
 let payload={};try{payload=await response.json()}catch{}
 if(!response.ok){
  const validation=payload.errors?Object.values(payload.errors).flat().join(' '):'';
  throw new Error(validation||payload.message||`Request failed (${response.status}).`);
 }
 return payload;
}
function normalizeCustomer(contact){
 const isCustomer=Boolean(contact.is_customer),isSupplier=Boolean(contact.is_supplier);
 return {...contact,phone:contact.phone||'',email:contact.email||'',billing_address:contact.billing_address||'',address:contact.billing_address||'',whatsapp:contact.phone||'',balance:Number(contact.opening_balance||0),contactType:isCustomer&&isSupplier?'Customer & supplier':isSupplier?'Supplier':'Customer'};
}
function findJobCustomer(customerId){if(walkInCustomer&&String(walkInCustomer.id)===String(customerId))return walkInCustomer;return customers.find(customer=>String(customer.id)===String(customerId))}
function jobCustomerOptions(){return walkInCustomer?[walkInCustomer,...customers]:customers}
function isWalkInCustomer(){return Boolean(walkInCustomer&&String(walkInCustomer.id)===String(draft.customerId))}
function defaultPaymentMethodId(){const cashMethod=jobcardPaymentMethods.find(method=>String(method.method_type||'').toLowerCase()==='cash');return String(cashMethod?.id||jobcardPaymentMethods[0]?.id||'')}
async function loadCustomers({force=false,quiet=false}={}){
 if(customersLoading&&!force)return;
 customersLoading=true;customersError='';
 try{
  const response=await apiRequest('/api/v1/customers?per_page=100');
  customers=(response.data||[]).map(normalizeCustomer);
  customerTotal=Number(response.total??customers.length);
  customersLoaded=true;
 }catch(error){
  customersError=error.message;customersLoaded=true;
  if(!quiet)toast('Customers could not be loaded: '+error.message);
  console.error('PressFlow customer API error',error);
 }finally{
  customersLoading=false;
  if(page==='customers'||page==='new-job')renderPage();
 }
}
async function loadWalkInCustomer({force=false}={}){
 if(walkInLoading&&!force)return;
 if(walkInLoaded&&!force)return;
 walkInLoading=true;walkInError='';
 try{
  const response=await apiRequest('/api/v1/customers?per_page=1&include_walk_in=1');
  walkInCustomer=(response.data||[]).map(normalizeCustomer).find(customer=>customer.is_default)||null;
  if(!walkInCustomer)walkInError='Walk-In Customer is not configured for this workspace.';
  walkInLoaded=true;
  if(page==='new-job'&&!draft.customerId&&walkInCustomer){
   draft.customerId=String(walkInCustomer.id);draft.orderBy=walkInCustomer.name;draft.phone=walkInCustomer.phone||'';draft.whatsapp=walkInCustomer.phone||'';
   loadCustomerOutstanding(walkInCustomer.id,{force:true});
  }
 }catch(error){
  walkInError=error.message;walkInLoaded=true;
  if(page==='new-job')toast('Walk-In Customer could not be loaded: '+error.message);
  console.error('PressFlow Walk-In Customer API error',error);
 }finally{
  walkInLoading=false;
  if(page==='new-job')renderPage();
 }
}
async function loadCustomerOutstanding(customerId,{force=false}={}){
 const key=String(customerId||'');
 if(!key)return;
 const existing=customerOutstandingById[key];
 if(existing?.loading||(!force&&existing?.loaded))return;
 const requestId=++customerOutstandingRequestId;
 customerOutstandingById[key]={...(existing||{}),loading:true,error:'',requestId};
 if(page==='new-job'&&String(draft.customerId)===key)renderPage();
 try{
  const response=await apiRequest(`/api/v1/customers/${encodeURIComponent(key)}/outstanding`);
  if(customerOutstandingById[key]?.requestId!==requestId)return;
  customerOutstandingById[key]={...response,loading:false,loaded:true,error:'',requestId};
 }catch(error){
  if(customerOutstandingById[key]?.requestId!==requestId)return;
  customerOutstandingById[key]={...(existing||{}),loading:false,loaded:false,error:error.message,requestId};
 }finally{
  if(customerOutstandingById[key]?.requestId===requestId&&page==='new-job'&&String(draft.customerId)===key)renderPage();
 }
}
async function loadJobcardMasters({force=false,quiet=false}={}){
 if(jobcardMastersLoading&&!force)return;
 const requestId=++jobcardMastersRequestId;jobcardMastersLoading=true;jobcardMastersError='';
 try{
  const response=await apiRequest('/api/v1/jobcard-masters');
  if(requestId!==jobcardMastersRequestId)return;
  const data=response.data||{};
  jobcardMasters={...jobcardMasters,...(data.masters||{}),digital_rates:data.digital_rates||[]};
  jobcardPaymentMethods=Array.isArray(data.payment_methods)?data.payment_methods:[];
  if(!draft.paymentMethodId&&jobcardPaymentMethods.length)draft.paymentMethodId=defaultPaymentMethodId();
  jobcardSettings={...jobcardSettings,...(data.settings||{})};
  jobcardMastersLoaded=true;
 }catch(error){
  if(requestId!==jobcardMastersRequestId)return;
  jobcardMastersError=error.message;jobcardMastersLoaded=true;
  if(!quiet)toast('Jobcard masters could not be loaded: '+error.message);
 }finally{
  if(requestId===jobcardMastersRequestId){jobcardMastersLoading=false;if(page==='jobcard-masters'||(page==='new-job'&&(newJobStep===2||newJobStep===3)))renderPage()}
 }
}
async function loadBusinessSettings({force=false,quiet=false}={}){
 if(businessSettingsLoading&&!force)return;
 businessSettingsLoading=true;businessSettingsError='';
 try{
  const response=await apiRequest('/api/v1/settings');
  businessSettings=response.data||{};businessSettingsLoaded=true;
  jobcardSettings={...jobcardSettings,...(businessSettings.jobcard||{})};
 }catch(error){
  businessSettingsError=error.message;businessSettingsLoaded=true;
  if(!quiet)toast('Jobcard settings could not be loaded: '+error.message);
 }finally{
  businessSettingsLoading=false;if(page==='settings'&&settingsTab==='Jobcards')renderPage();
 }
}
