function orderItemTotals(items=[]){let totalSqf=0,totalPics=0;for(const item of items){const spec=item.specifications||{},category=String(spec.category||'').toLowerCase(),unit=String(item.unit||'').toLowerCase().replace(/\s+/g,''),quantity=Number(item.quantity||0),isSquareFoot=['sqft','sqfeet','squarefeet'].includes(unit);if(category==='flex'){totalSqf+=Number(spec.area_sq_ft??quantity);totalPics+=Number(spec.pieces||0)}else if(isSquareFoot){totalSqf+=Number(spec.area_sq_ft??quantity);totalPics+=Number(spec.pieces||0)}else totalPics+=Number(spec.pieces??quantity)}return {totalSqf:round2(totalSqf),totalPics:round2(totalPics)}}
