 const customer=order.customer||{},stage=order.production_stage||'new',printType=String(order.print_type||'other');
 const items=Array.isArray(order.items)?order.items:[],invoices=Array.isArray(order.invoices)?order.invoices:[],events=Array.isArray(order.events)?order.events:[];
 const total=Number(order.total||0),paidAmount=invoices.reduce((sum,invoice)=>sum+Number(invoice.paid_total||0),0),itemTotals=orderItemTotals(items);
 const balanceDue=invoices.length?invoices.reduce((sum,invoice)=>sum+Math.max(0,Number(invoice.total||0)-Number(invoice.paid_total||0)),0):Math.max(0,total-paidAmount);
 const createdEvent=events.find(event=>!event.from_stage),approvalEvent=events.find(event=>event.to_stage==='proof_approved');
 return {...order,ref:order.job_number||`PF-${order.id}`,item:order.job_number||`PF-${order.id}`,customer:customer.name||'—',contact:order.contact_phone||customer.phone||'',subject:order.title||'Print job',type:printType.charAt(0).toUpperCase()+printType.slice(1),priority:String(order.priority||'normal').replace(/^./,x=>x.toUpperCase()),start:displayDate(order.job_date||order.created_at),jobTime:displayTime(order.created_at),due:displayDate(order.due_at),deliveryTime:displayTime(order.due_at),orderBy:order.contact_name||customer.name||'—',mobile:order.contact_phone||customer.phone||'—',whatsapp:order.whatsapp_phone||'—',userName:order.created_by_name||createdEvent?.changed_by?.name||'—',designApprovedBy:order.design_approved_by_name||approvalEvent?.changed_by?.name||'—',editedBy:order.edited_by_name||'—',totalSqf:itemTotals.totalSqf,totalPics:itemTotals.totalPics,invoiceExists:invoices.length>0,paidAmount,balanceDue,status:orderStageLabel(stage),amount:total,production_stage:stage}
}
