function pageName(id){for(const g of navGroups){const found=g.items.find(x=>x[0]===id);if(found)return tr(found[2])}return id}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="page-eyebrow">${esc(workspaceName)} · workspace</div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div><div class="actions">${actions}</div></div>`}
function statusClass(s){const v=String(s||'').toLowerCase();if(v.includes('paid')||v.includes('delivered')||v.includes('complete')||v.includes('received')||v.includes('ready'))return 'active';if(v.includes('overdue')||v.includes('cancel'))return 'overdue';if(v.includes('design')||v.includes('approve')||v.includes('proof'))return 'design';if(v.includes('progress')||v.includes('printing')||v.includes('converted')||v.includes('sent')||v.includes('prepress')||v.includes('finishing'))return 'progress';if(v.includes('draft'))return 'draft';return 'pending'}
function statusTag(s){return `<span class="list-status ${statusClass(s)}">${esc(s)}</span>`}
function tableHtml(cols,rows,empty='No records found.'){if(!rows.length)return `<div class="empty">${esc(empty)}</div>`;return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((row,rowIndex)=>`<tr>${cols.map(c=>`<td>${c.render?c.render(row,rowIndex):esc(row[c.key]??'—')}</td>`).join('')}<td><button class="action-more" data-action="row-menu" data-row-id="${esc(row.id??'')}" title="More">•••</button></td></tr>`).join('')}</tbody></table></div>`}
function kpi(icon,val,label,count=''){return `<div class="kpi"><div class="kpi-top"><span class="kpi-icon">${icon}</span>${count?`<span class="kpi-mini">${count}</span>`:''}</div><div class="kpi-val">${val}</div><div class="kpi-label">${label}</div></div>`}
function dashboard(){
