  {label:'Finishing',keys:['finishing'],color:'#f4aa60'},
  {label:'Ready',keys:['ready'],color:'#65bd88'}
 ].map(x=>({...x,count:x.keys.reduce((sum,key)=>sum+Number(stageData[key]||0),0)}));
 const stageTotal=stageGroups.reduce((sum,x)=>sum+x.count,0);
 let cursor=0;
 const segments=stageGroups.map(x=>{const from=cursor;cursor+=stageTotal?x.count/stageTotal*100:0;return `${x.color} ${from.toFixed(2)}% ${cursor.toFixed(2)}%`}).join(',');
 const donutBackground=stageTotal?`conic-gradient(${segments})`:'conic-gradient(#d6dee8 0 100%)';
 const due=dashboardSummary?.due_date_counts||{};
 const dueBars=[['Overdue',Number(due.overdue||0),'overdue'],['Today',Number(due.today||0),''],['Tomorrow',Number(due.tomorrow||0),''],['In 2 days',Number(due.in_two_days||0),''],['In 3–7 days',Number(due.next_3_to_7_days||0),''],['Over 7 days',Number(due.over_7_days||0),'']];
 const maxDue=Math.max(1,...dueBars.map(x=>x[1]));
 const actions=`<button class="btn" data-action="refresh-dashboard">↻ &nbsp;Refresh</button>${canCreateOrders?'<button class="btn primary" data-action="new-job">＋ &nbsp;New jobcard</button>':''}`;
 const apiBanner=dashboardError?`<div class="demo-flag">Dashboard data could not be loaded: ${esc(dashboardError)} <button data-action="refresh-dashboard">Retry</button></div>`:dashboardSummary?`<div class="live-flag">Live dashboard summary and recent jobcards are loaded from this workspace database. Invoice, quote and other module screens are still being connected.</div>`:`<div class="demo-flag">Loading workspace dashboard data…</div>`;
 return `${head('Dashboard','Your print shop at a glance · '+new Date().toLocaleDateString('en-GB',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}),actions)}${apiBanner}
 <div class="kpi-grid">${kpi('▣',dashboardSummary?Number(dashboardSummary.open_orders||0):'—','Open jobcards')}${kpi('⚙',dashboardSummary?Number(dashboardSummary.in_production||0):'—','In production')}${kpi('◷',dashboardSummary?Number(dashboardSummary.due_today||0):'—','Due today')}${kpi('↗',dashboardSummary?money(dashboardSummary.revenue_this_month):'—','Received this month')}${kpi('＄',dashboardSummary?money(dashboardSummary.outstanding_balance):'—','Outstanding invoices')}${kpi('!',dashboardSummary?Number(dashboardSummary.overdue_invoices||0):'—','Overdue invoices')}</div>
 <div class="dash-grid"><section class="card chart-panel"><div class="card-head"><div><h3>Open jobs by production stage</h3><p>${dashboardSummary?`Workspace totals · ${stageTotal} open job(s)`:'Loading from database…'}</p></div><button class="text-link" data-page="job-status">Open production →</button></div><div class="chart-area"><div class="donut-layout"><div class="donut" style="background:${donutBackground}"><div class="donut-center"><strong>${dashboardSummary?Number(dashboardSummary.open_orders||0):'—'}</strong><span>Open jobs</span></div></div><div class="legend">${stageGroups.map(x=>`<div class="legend-row"><i class="legend-dot" style="background:${x.color}"></i>${esc(x.label)} <b>${x.count}</b></div>`).join('')}</div></div></div></section>
 <section class="card chart-panel"><div class="card-head"><div><h3>Jobs by due date</h3><p>Open jobs · due-date forecast</p></div><button class="text-link" data-page="job-cards">Open jobcards →</button></div><div class="chart-area"><div class="bar-chart"><div class="bars">${dueBars.map(x=>`<div class="bar-group"><div class="bar ${x[2]}" style="height:${Math.max(x[1]?8:3,x[1]/maxDue*104)}px"></div><span class="bar-tick">${x[1]}</span><span class="bar-tick">${x[0]}</span></div>`).join('')}</div><div class="chart-axis"><span>0</span><span>2</span><span>4</span><span>6</span><span>${maxDue} jobs</span></div></div></div></section></div>
 <div class="bottom-grid"><section class="card"><div class="card-head"><div><h3>Recent jobcards</h3><p>Latest jobs from the shared workspace database</p></div><button class="text-link" data-action="refresh-orders">Refresh jobs</button></div>${tableHtml([{label:'Job No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Customer',key:'customer'},{label:'Job / Subject',key:'subject'},{label:'Priority',key:'priority',render:r=>`<span class="priority ${r.priority==='High'?'high':'normal'}">${esc(r.priority)}</span>`},{label:'Due Date',key:'due'},{label:'Status',key:'status',render:r=>statusTag(r.status)}],rows,ordersLoading?'Loading recent jobcards…':'No jobcards have been saved yet.')}</section>
 <section class="card"><div class="card-head"><div><h3>Outstanding reminders</h3><p>Current invoice balance summary</p></div><span class="chip red">${dashboardSummary?money(dashboardSummary.outstanding_balance):'—'}</span></div><div class="card-body"><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div style="background:#fff2f1;padding:10px;border-radius:7px"><small style="font-size:10px;color:#a77675">OUTSTANDING BALANCE</small><strong style="display:block;margin-top:4px;font-size:14.4px;color:#aa4b4b">${dashboardSummary?money(dashboardSummary.outstanding_balance):'—'}</strong></div><div style="background:#f3f6fa;padding:10px;border-radius:7px"><small style="font-size:10px;color:#8793a0">OVERDUE INVOICES</small><strong style="display:block;margin-top:4px;font-size:14.4px">${dashboardSummary?Number(dashboardSummary.overdue_invoices||0):'—'}</strong></div></div><p class="task-note" style="margin:12px 0 0">Invoice, receipt and payment detail screens are still preview-only; they will be connected in the next integration phase.</p></div></section></div><div class="demo-note">Jobcard and production figures come from Laravel. Other modules will be connected separately.</div>`}
function orderConnectionBanner(){if(ordersError)return `<div class="demo-flag">Could not load workspace jobcards: ${esc(ordersError)} <button data-action="refresh-orders">Retry</button></div>`;if(!ordersLoaded)return '<div class="demo-flag">Loading jobcards from the workspace database…</div>';return `<div class="live-flag">Connected to the workspace database · ${orderTotal} jobcard(s). Stage changes are validated and audit-logged. ${ordersLoading?'Refreshing…':''}</div>`}
function orderFiltersHtml(){const options=[['new','New'],['proof','Prepress / proof'],['production','Proof approved / printing'],['finishing','Finishing'],['ready','Ready'],['delivered','Delivered'],['cancelled','Cancelled']];return `<div class="filters"><label>Production stage</label><select class="select" data-order-status><option value="">All stages</option>${options.map(([value,label])=>`<option value="${value}" ${ordersStatus===value?'selected':''}>${label}</option>`).join('')}</select><input class="search" data-page-search value="${esc(ordersSearch)}" placeholder="Search job number, customer, title…"><button class="btn ghost" data-action="apply-order-filters">⌕ Search</button><button class="btn" data-action="refresh-orders">↻ Refresh</button></div>`}
function orderPaginationHtml(count){const first=count?(ordersCurrentPage-1)*ordersPerPage+1:0,last=Math.min(ordersCurrentPage*ordersPerPage,orderTotal);return `<div class="table-foot"><span>Showing ${first}–${last} of ${orderTotal} records</span><div class="table-tools"><button class="btn sm" data-action="orders-page" data-page-number="${Math.max(1,ordersCurrentPage-1)}" ${ordersCurrentPage<=1?'disabled':''}>‹ Previous</button><span>Page ${ordersCurrentPage} of ${ordersLastPage}</span><button class="btn sm" data-action="orders-page" data-page-number="${Math.min(ordersLastPage,ordersCurrentPage+1)}" ${ordersCurrentPage>=ordersLastPage?'disabled':''}>Next ›</button></div></div>`}
function genericList(id){let cfg;
 if(id==='job-cards'){
  cfg={title:'Job Cards',sub:'Workspace jobcards loaded from Laravel. Scroll horizontally to view all job and payment details.',rows:jobs,cols:[
   {label:'SR',render:(r,index)=>(ordersCurrentPage-1)*ordersPerPage+index+1},
   {label:'Job Date ▾',key:'start'},
   {label:'Job Time',key:'jobTime'},
   {label:'Job No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},
   {label:'Customer Name',key:'customer'},
   {label:'Order By',key:'orderBy'},
   {label:'Mobile No',key:'mobile'},
   {label:'WhatsApp No',key:'whatsapp'},
   {label:'User Name',key:'userName'},
   {label:'Design Approved By',key:'designApprovedBy'},
   {label:'Total SQ',render:r=>listNumber(r.totalSqf)},
   {label:'Total Pics',render:r=>listCount(r.totalPics)},
   {label:'Final Bill',render:r=>listNumber(r.amount)},
   {label:'Paid Amount',render:r=>`<button type="button" class="paid-amount-link" data-action="show-payment-receipts" data-order-id="${esc(r.id)}" aria-label="View payment receipts for ${esc(r.ref)}">${listNumber(r.paidAmount)}</button>`},
   {label:'Balance Due',render:r=>listNumber(r.balanceDue)},
   {label:'Invoice',render:r=>r.invoiceExists?'<span class="list-status active">Yes</span>':'<span class="list-status pending">No</span>'},
   {label:'Status',key:'status',render:r=>statusTag(r.status)},
   {label:'Delivery Date',key:'due'},
   {label:'Delivery Time',key:'deliveryTime'},
   {label:'Edited By',key:'editedBy'}
  ]};
 }else if(['orders','designer-work','printer-work'].includes(id)){cfg={title:pageName(id),sub:'Workspace jobcards loaded from Laravel. Use the production-stage filter to focus this list.',rows:jobs,cols:[{label:'Job No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Job Date',key:'start'},{label:'Customer',key:'customer'},{label:'Job / Subject',key:'subject'},{label:'Type',key:'type'},{label:'Priority',key:'priority'},{label:'Due Date',key:'due'},{label:'Amount',render:r=>money(r.amount)},{label:'Production Stage',key:'status',render:r=>statusTag(r.status)}]};}
 else if(id==='estimates'||id==='quotations')cfg={title:pageName(id),sub:'Prepare, send and convert customer estimates into jobcards.',rows:quotes,cols:[{label:'Estimate No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Date',key:'date'},{label:'Customer',key:'customer'},{label:'Valid Until',key:'expiry'},{label:'Amount',render:r=>money(r.amount)},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='invoices')cfg={title:'Invoice List',sub:'Manage normal bills, tax invoices, balances and customer receipts.',rows:invoices,cols:[{label:'Invoice Date',key:'date'},{label:'Invoice No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Customer Name',key:'customer'},{label:'Mobile No',key:'phone'},{label:'Amount',render:r=>money(r.amount)},{label:'TDS / Tax',render:r=>money(r.tds)},{label:'Balance',render:r=>money(r.balance)},{label:'Job No',key:'job'},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='payments')cfg={title:'Payment List',sub:'View payments received or made, filtered by period and payment mode.',rows:payments,cols:[{label:'Payment No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Payment Date',key:'date'},{label:'Payee Name',key:'payee'},{label:'Amount',render:r=>money(r.amount)},{label:'Mode',key:'mode'},{label:'Remark',key:'remark'},{label:'User Name',key:'user'}]};
 else if(id==='receipts')cfg={title:'Receipt List',sub:'Track receipts against invoices, advance payments and customer balances.',rows:receipts,cols:[{label:'Receipt No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Receipt Date',key:'date'},{label:'Customer',key:'customer'},{label:'Invoice No',key:'invoice'},{label:'Amount',render:r=>money(r.amount)},{label:'Mode',key:'mode'}]};
 else if(id==='purchases')cfg={title:'Purchase Register',sub:'Record supplier purchases and monitor incoming print materials.',rows:purchases,cols:[{label:'Purchase No',key:'ref',render:r=>`<span class="ref">${esc(r.ref)}</span>`},{label:'Supplier',key:'supplier'},{label:'Date',key:'date'},{label:'Items',key:'items'},{label:'Amount',render:r=>money(r.amount)},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='delivery-challan')cfg={title:'Delivery Challan',sub:'Prepare delivery notes and track handover of completed jobs.',rows:demoJobs.filter(j=>['Fabrication Done','Delivered'].includes(j.status)).map((j,i)=>({...j,challan:'DC-00'+(483+i)})),cols:[{label:'Challan No',key:'challan',render:r=>`<span class="ref">${esc(r.challan)}</span>`},{label:'Date',key:'due'},{label:'Customer',key:'customer'},{label:'Job No',key:'ref'},{label:'Contact',key:'contact'},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='employees')cfg={title:'Employee Master',sub:'Manage team members, departments, access and assigned work.',rows:employees,cols:[{label:'Employee ID',key:'id',render:r=>`<span class="ref">${esc(r.id)}</span>`},{label:'Name',key:'name'},{label:'Role',key:'role'},{label:'Mobile',key:'phone'},{label:'Active Jobs',key:'assigned'},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='customers')cfg={title:'Customer Master',sub:'Workspace contacts loaded from the Laravel database. Create and edit contacts here.',rows:customers,cols:[{label:'Customer / Supplier',key:'name',render:r=>`<span class="client">${esc(r.name)}</span><span class="client-sub">${esc(r.email||r.contact_code||'')}</span>`},{label:'Mobile',key:'phone'},{label:'Billing address',key:'address'},{label:'Contact type',key:'contactType'},{label:'Credit limit',render:r=>r.credit_limit===null||r.credit_limit===undefined?'—':money(r.credit_limit)},{label:'Orders',key:'orders_count'}]};
 else if(id==='inventory')cfg={title:'Inventory & Materials',sub:'Monitor stock on hand and materials used for current jobs.',rows:[{sku:'MAT-001',name:'Flex media roll · 5ft',category:'Flex media',unit:'Roll',stock:12,reorder:5,rate:18500},{sku:'MAT-002',name:'Art paper · 250gsm',category:'Paper',unit:'Ream',stock:9,reorder:12,rate:7200},{sku:'MAT-003',name:'CMYK ink set',category:'Ink',unit:'Set',stock:4,reorder:3,rate:36500},{sku:'MAT-004',name:'Cold laminate · 5ft',category:'Finishing',unit:'Roll',stock:2,reorder:4,rate:22300}],cols:[{label:'SKU',key:'sku',render:r=>`<span class="ref">${esc(r.sku)}</span>`},{label:'Material',key:'name'},{label:'Category',key:'category'},{label:'Unit',key:'unit'},{label:'On Hand',key:'stock'},{label:'Reorder At',key:'reorder'},{label:'Unit Cost',render:r=>money(r.rate)},{label:'Status',render:r=>statusTag(r.stock<=r.reorder?'Reorder':'Available')}]};
 else if(id==='products')cfg={title:'Products & Media',sub:'Manage print products, media types, fabrication and standard rates.',rows:[{sku:'PRD-001',name:'Flex Banner',media:'Frontlit 440gsm',size:'Custom',rate:1850,unit:'sq ft',status:'Active'},{sku:'PRD-002',name:'Business Cards',media:'300gsm Art Card',size:'3.5 × 2 in',rate:95,unit:'piece',status:'Active'},{sku:'PRD-003',name:'Vinyl Sticker',media:'Gloss Vinyl + Lamination',size:'Custom',rate:2250,unit:'sq ft',status:'Active'},{sku:'PRD-004',name:'A3 Poster',media:'Art Paper 170gsm',size:'A3',rate:680,unit:'piece',status:'Active'}],cols:[{label:'Product Code',key:'sku'},{label:'Product',key:'name'},{label:'Media / Material',key:'media'},{label:'Size',key:'size'},{label:'Rate',render:r=>money(r.rate)},{label:'Unit',key:'unit'},{label:'Status',key:'status',render:r=>statusTag(r.status)}]};
 else if(id==='attendance')return attendancePage();
 else if(id==='access-control')return accessPage();
 else if(['chart-accounts','journal','contra','cash-book','bank-book','trial-balance','balance-sheet','day-closing'].includes(id))return accountingPage(id);
 else return `${head(pageName(id),'Manage '+pageName(id).toLowerCase()+' in your print shop workspace.',`<button class="btn primary" data-action="generic-add">＋ &nbsp;Add ${esc(pageName(id).replace(/s$/,''))}</button>`)}<section class="card"><div class="card-body"><div class="empty">This screen is ready in the new navigation layout. Configure this master list for your shop during setup.</div></div></section>`;
 const orderList=['orders','job-cards','designer-work','printer-work'].includes(id);
 const actionLabel=orderList?'New jobcard':id==='invoices'?'New invoice':id==='estimates'||id==='quotations'?'New quotation':id==='purchases'?'New purchase':id==='employees'?'Add employee':id==='customers'?'Add customer':id==='delivery-challan'?'New challan':`New ${pageName(id).replace(/s$/,'')}`;
 const action=`${orderList?'<button class="btn" data-action="refresh-orders">↻ &nbsp;Refresh</button>':'<button class="btn" data-action="export">⇩ &nbsp;Export</button>'}${orderList&&!canCreateOrders?'':`<button class="btn primary" data-action="${orderList?'new-job':id==='customers'?'add-customer':'generic-add'}">＋ &nbsp;${esc(actionLabel)}</button>`}`;
 const banner=orderList?orderConnectionBanner():id==='customers'?(customersLoading?'<div class="demo-flag">Loading contacts from the workspace database…</div>':customersError?`<div class="demo-flag">Could not load contacts: ${esc(customersError)} <button data-action="refresh-customers">Retry</button></div>`:`<div class="live-flag">Connected to the workspace database · ${customerTotal} contact(s). Add and edit operations are saved immediately. <button data-action="refresh-customers">Refresh</button></div>`):'<div class="demo-flag">Preview data only. This page is not connected to Laravel yet.</div>';
 const filters=orderList?orderFiltersHtml():`<div class="filters"><label>From</label><input class="input" type="date" value="2026-08-01"><label>To</label><input class="input" type="date" value="2026-09-01">${id==='invoices'?'<select class="select"><option>All customers</option>'+customers.map(c=>`<option>${esc(c.name)}</option>`).join('')+'</select>':''}<select class="select"><option>All statuses</option><option>Pending</option><option>In Progress</option><option>Paid</option><option>Overdue</option></select><input class="search" data-page-search placeholder="Search by number, customer, job…"><button class="btn ghost" data-action="filter">⌕ Filter</button></div>`;
 const rowCount=orderList?orderTotal:id==='customers'?customerTotal:cfg.rows.length;
 const subText=id==='customers'?`${customerTotal} contacts · from this workspace`:orderList?`${orderTotal} jobcards · from this workspace`:`${cfg.rows.length} records · sorted by latest activity`;
 const emptyText=orderList?(ordersLoading&&!ordersLoaded?'Loading jobcards…':'No jobcards match this filter.'):'No records found.';
 const foot=orderList?orderPaginationHtml(cfg.rows.length):`<div class="table-foot"><span>Showing ${cfg.rows.length?1:0}–${cfg.rows.length} of ${rowCount} records</span><span>‹ &nbsp; Page 1 of 1 &nbsp; ›</span></div>`;
 return `${head(cfg.title,cfg.sub,action)}${banner}${filters}<section class="card table-card"><div class="card-head"><div><h3>${esc(cfg.title)}</h3><p>${subText}</p></div><div class="table-tools"><button class="btn sm" data-action="print">⎙ Print</button>${orderList?'<button class="btn sm" data-action="refresh-orders">↻ Refresh</button>':'<button class="btn sm" data-action="export">↓ Excel</button><button class="btn sm" data-action="export">PDF</button>'}</div></div><div id="genericTable" class="${id==='job-cards'?'job-cards-table':''}">${tableHtml(cfg.cols,cfg.rows,emptyText)}</div>${foot}</section>`}
function productionStageControls(order){const next=ORDER_TRANSITIONS[order.production_stage]||[];if(!canManageProduction)return '<span class="task-note">View only</span>';if(!next.length)return '<span class="task-note">No further stages</span>';return `<div class="job-stage-controls"><select data-stage-select aria-label="Move ${esc(order.ref)} to next stage"><option value="">Move to…</option>${next.map(stage=>`<option value="${stage}">${esc(orderStageLabel(stage))}</option>`).join('')}</select><button class="btn sm primary" data-action="move-stage" data-order-id="${order.id}">Move</button></div>`}
function statusBoard(){const stages=['new','prepress','proof_approved','printing','finishing','ready','delivered','cancelled'];const actions=`<button class="btn" data-action="refresh-orders">↻ &nbsp;Refresh</button>${canCreateOrders?'<button class="btn primary" data-action="new-job">＋ New jobcard</button>':''}`;const notice=ordersError?`<div class="demo-flag">Could not load production jobs: ${esc(ordersError)} <button data-action="refresh-orders">Retry</button></div>`:ordersLoaded?`<div class="live-flag">Production workflow is connected to Laravel · ${jobs.length} job(s) loaded of ${orderTotal}. Stage moves are validated, timestamped and audit-logged.${ordersLoading?' Refreshing…':''}</div>`:'<div class="demo-flag">Loading production jobs from the workspace database…</div>';return `${head('Job Status','Production workflow · move jobs through validated stages',actions)}${notice}<div class="filters"><input class="search" placeholder="Search job number, title or customer…" data-board-search><span class="pill-tag">${jobs.length} loaded · ${orderTotal} total</span></div><div class="status-board">${stages.map(stage=>{const list=jobs.filter(j=>j.production_stage===stage);return `<section class="status-col"><div class="status-col-head"><strong>${esc(orderStageLabel(stage))}</strong><span>${list.length}</span></div>${list.length?list.map(order=>`<article class="job-mini" data-order-id="${order.id}"><strong>${esc(order.ref)}</strong><h4>${esc(order.subject)}</h4><p>${esc(order.customer)} · ${esc(order.type)}</p><div class="job-mini-foot"><span>Due ${esc(order.due)}</span><b>${money(order.amount)}</b></div><div class="job-mini-actions"><button class="text-link" data-action="view-order" data-order-id="${order.id}">Details &amp; history</button>${productionStageControls(order)}</div></article>`).join(''):'<div class="empty" style="padding:18px 6px">No jobs in this stage.</div>'}</section>`}).join('')}</div>${orderPaginationHtml(jobs.length)}<div class="demo-note">Jobcard creation and stage history are saved to the tenant database. Invoices and payments remain in preview mode.</div>`}
function reportsPage(){return `${head('Reports','Explore print-shop performance, finance, production and customer activity.',`<button class="btn">This month ▾</button><button class="btn" data-action="export">↓ Export</button>`)}<div class="demo-flag">24 report modules based on your screenshots; each report will be wired to Laravel queries and export jobs in the next implementation phase.</div><div class="cards-grid">${reports.map(([name,icon])=>`<article class="card report-card" data-report="${esc(name)}"><div class="master-icon">${icon}</div><div><strong>${esc(name)}</strong><small>Open report &amp; choose date range</small></div></article>`).join('')}</div>`}
function taxPage(){const rateRows=taxRates.map(r=>({...r,calculation:r.calculation_type==='percentage'?'Percentage':'Fixed amount',display_rate:r.calculation_type==='percentage'?`${Number(r.rate).toFixed(4).replace(/0+$/,'').replace(/\.$/,'')}%`:money(r.rate),groups:taxGroups.filter(g=>g.rateIds.includes(r.id)).map(g=>g.name).join(', ')||'—'}));const groupRows=taxGroups.map(g=>({...g,mode:g.is_inclusive?'Tax-inclusive':'Tax-exclusive',rates:g.rateIds.map(id=>taxRates.find(r=>r.id===id)?.name).filter(Boolean).join(' + '),status:g.is_active?'Active':'Inactive'}));return `${head('Tax Rates & Groups','Configure tax rates, tax groups, and inclusive or exclusive pricing for this business.',`<button class="btn" data-action="tax-add-rate">＋ New tax rate</button><button class="btn primary" data-action="tax-add-group">＋ New tax group</button>`)}<div class="demo-flag">Taxes are configured per business. Tax group and rate snapshots will be stored on finalized purchases and invoices, so later tax changes will not rewrite old records. Sample rates below are for interface preview only—confirm applicable tax rules before use.</div><section class="card"><div class="item-tabs"><button class="item-tab ${taxTab==='rates'?'active':''}" data-tax-tab="rates">Tax Rates <span class="nav-count">${taxRates.length}</span></button><button class="item-tab ${taxTab==='groups'?'active':''}" data-tax-tab="groups">Tax Groups <span class="nav-count">${taxGroups.length}</span></button><button class="item-tab ${taxTab==='calculator'?'active':''}" data-tax-tab="calculator">Tax Calculator</button></div><div class="card-body">${taxTab==='rates'?`<div class="table-tools" style="justify-content:space-between;margin-bottom:12px"><div><strong style="font-size:12px">Tax rates</strong><div style="font-size:10px;color:var(--muted);margin-top:4px">Rate, type, effective dates and group usage.</div></div><button class="btn sm primary" data-action="tax-add-rate">＋ Add rate</button></div>${tableHtml([{label:'Code',key:'code',render:r=>`<span class="ref">${esc(r.code)}</span>`},{label:'Tax name',key:'name'},{label:'Calculation',key:'calculation'},{label:'Rate',key:'display_rate'},{label:'Valid from',key:'valid_from'},{label:'Valid until',key:'valid_until',render:r=>r.valid_until||'No end date'},{label:'Tax groups',key:'groups'},{label:'Status',key:'is_active',render:r=>statusTag(r.is_active?'Active':'Inactive')}],rateRows)}`:taxTab==='groups'?`<div class="table-tools" style="justify-content:space-between;margin-bottom:12px"><div><strong style="font-size:12px">Tax groups</strong><div style="font-size:10px;color:var(--muted);margin-top:4px">Combine one or more rates; choose how invoice prices are treated.</div></div><button class="btn sm primary" data-action="tax-add-group">＋ Add group</button></div>${tableHtml([{label:'Code',key:'code',render:r=>`<span class="ref">${esc(r.code)}</span>`},{label:'Group name',key:'name'},{label:'Included rates',key:'rates'},{label:'Price handling',key:'mode'},{label:'Status',key:'status',render:r=>statusTag(r.status)}],groupRows)}`:`<div class="tax-calculator"><div><h3>Tax preview</h3><p>Check the calculated total before a sale or purchase. Final amounts are recalculated and stored by Laravel.</p><div class="settings-form"><div class="field"><label>Tax group</label><select class="select" id="taxPreviewGroup">${taxGroups.filter(g=>g.is_active).map(g=>`<option value="${g.id}">${esc(g.name)} · ${g.is_inclusive?'inclusive':'exclusive'}</option>`).join('')}</select></div><div class="field"><label>Entered amount (LKR)</label><input class="input" id="taxPreviewAmount" type="number" min="0" step="0.01" value="10000"></div><div class="field"><label>Quantity (for fixed rates)</label><input class="input" id="taxPreviewQty" type="number" min="0.0001" step="0.01" value="1"></div></div><button class="btn primary" style="margin-top:12px" data-action="tax-calc">Calculate tax</button></div><div id="taxPreviewResult" class="tax-preview-result"><strong>Preview result</strong><p>Select a group and calculate to see taxable amount, tax components and total.</p></div></div>`}</div></section>`}
function masterDataPage(){return `${head('Master Data','Set up the reference lists that power job entry and production.',`<button class="btn" data-action="import">⇧ Import</button><button class="btn primary" data-page="jobcard-masters">＋ Jobcard pricing masters</button>`)}<div class="live-flag">Jobcard media, fabrication, digital price matrix and other-item masters are tenant-scoped and used by the jobcard wizard. Other master cards remain preview-only.</div><div class="cards-grid">${masterCards.map(([name,icon,target])=>`<article class="card master-card" data-page="${target}"><div class="master-icon">${icon}</div><div><strong>${esc(name)}</strong><small>Manage ${esc(name.toLowerCase())} records</small></div></article>`).join('')}</div>`}
function masterTypeLabel(type){return Object.fromEntries(JOBCARD_MASTER_TABS)[type]||type}
function jobcardMasterOptions(type,value=''){const records=jobcardMasters[type]||[];return `<option value="">Select ${esc(masterTypeLabel(type).toLowerCase())}…</option>${records.filter(m=>m.is_active||String(m.id)===String(value)).map(m=>`<option value="${m.id}" ${String(m.id)===String(value)?'selected':''}>${esc(m.name)}${m.is_active?'':' (Inactive)'}</option>`).join('')}`}
function jobcardMasterById(type,id){return (jobcardMasters[type]||[]).find(m=>String(m.id)===String(id))||null}
function jobcardMasterPage(){const type=jobcardMasterTab;const title=masterTypeLabel(type);const actions=`${canManageJobcardMasters?`<button class="btn primary" data-action="jobcard-master-add">＋ ${type==='digital_rates'?'Add price combination':'Add '+esc(title)}</button>`:''}<button class="btn" data-action="refresh-jobcard-masters">↻ Refresh</button>`;const notice=jobcardMastersError?`<div class="demo-flag">Could not load Jobcard Masters: ${esc(jobcardMastersError)} <button data-action="refresh-jobcard-masters">Retry</button></div>`:jobcardMastersLoading?'<div class="demo-flag">Loading tenant Jobcard Masters…</div>':`<div class="live-flag">${canManageJobcardMasters?'Masters and prices are saved for this workspace. Add your own rates; no sample prices are applied.':'View-only Jobcard Masters for this workspace.'}</div>`;let table='';if(type==='digital_rates'){const rows=jobcardMasters.digital_rates||[];table=rows.length?`<div class="table-wrap"><table><thead><tr><th>Particular</th><th>Media</th><th>Size</th><th>Side</th><th>Rate / unit</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.particular?.name||'—')}</td><td>${esc(r.media?.name||'—')}</td><td>${esc(r.size?.name||'—')}</td><td>${esc(r.side?.name||'—')}</td><td>${money(r.rate)}</td><td>${statusTag(r.is_active?'Active':'Inactive')}</td><td>${canManageJobcardMasters?`<button class="btn sm" data-action="edit-jobcard-rate" data-id="${r.id}">Edit</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No Digital/Paper price combinations yet. Add one after creating active Particular, Media, Size and Side masters.</div>'}else{const records=(jobcardMasters[type]||[]);table=records.length?`<div class="table-wrap"><table><thead><tr><th>Name</th>${['digital_particular','other_item'].includes(type)?'<th>Unit</th>':''}${['flex_media','other_item','fabrication'].includes(type)?'<th>Default rate / charge</th>':''}${type==='fabrication'?'<th>Charge mode</th>':''}<th>Status</th><th></th></tr></thead><tbody>${records.map(m=>`<tr><td>${esc(m.name)}</td>${['digital_particular','other_item'].includes(type)?`<td>${esc(m.unit||'—')}</td>`:''}${['flex_media','other_item','fabrication'].includes(type)?`<td>${money(m.rate||0)}${type==='flex_media'?' / sq ft':''}</td>`:''}${type==='fabrication'?`<td>${esc(({none:'No extra charge',per_piece:'Per piece',per_sq_ft:'Per sq ft',flat_per_line:'Flat per line'})[m.charge_mode]||m.charge_mode||'—')}</td>`:''}<td>${statusTag(m.is_active?'Active':'Inactive')}</td><td>${canManageJobcardMasters?`<button class="btn sm" data-action="edit-jobcard-master" data-type="${type}" data-id="${m.id}">Edit</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No ${esc(title.toLowerCase())} masters yet. ${canManageJobcardMasters?'Use “Add” to create the first one.':''}</div>`}return `${head('Jobcard Masters & Pricing','Create tenant-specific dropdowns, rates and calculation rules used when saving jobcards.',actions)}${notice}<section class="card"><div class="item-tabs">${JOBCARD_MASTER_TABS.map(([key,label])=>`<button class="item-tab ${type===key?'active':''}" data-jobcard-master-tab="${key}">${esc(label)}${key==='digital_rates'?` <span class="tab-count">${jobcardMasters.digital_rates.length}</span>`:` <span class="tab-count">${(jobcardMasters[key]||[]).length}</span>`}</button>`).join('')}</div><div class="card-body">${table}</div></section><div class="demo-note">Digital/Paper prices are matched by Particular + Media + Size + Side. Flex area is calculated in square feet from feet or inches; fabrication charges follow the selected fabrication master.</div>`}
function jobcardMasterModal(type,id=null){const isRate=type==='digital_rates';const record=isRate?(jobcardMasters.digital_rates||[]).find(x=>String(x.id)===String(id)):id?jobcardMasterById(type,id):null;if(id&&!record){toast('That master record was not found. Refresh and try again.');return}let fields='';if(isRate){fields=`<div class="field"><label>Particular *</label><select class="select" name="particular_id" required>${jobcardMasterOptions('digital_particular',record?.particular_id)}</select></div><div class="field"><label>Media *</label><select class="select" name="media_id" required>${jobcardMasterOptions('digital_media',record?.media_id)}</select></div><div class="field"><label>Size *</label><select class="select" name="size_id" required>${jobcardMasterOptions('digital_size',record?.size_id)}</select></div><div class="field"><label>Side *</label><select class="select" name="side_id" required>${jobcardMasterOptions('digital_side',record?.side_id)}</select></div><div class="field"><label>Rate per unit (LKR) *</label><input class="input" name="rate" type="number" min="0" step="0.01" required value="${esc(record?.rate??'')}"></div>${record?`<div class="field"><label><input type="checkbox" name="is_active" ${record.is_active?'checked':''}> Active</label></div>`:''}`}else{fields=`<div class="field"><label>Name *</label><input class="input" name="name" maxlength="120" required value="${esc(record?.name||'')}"></div><div class="field"><label>Code (optional)</label><input class="input" name="code" maxlength="48" value="${esc(record?.code||'')}"></div>`;if(type==='flex_media')fields+=`<div class="field"><label>Default rate per sq ft (LKR) *</label><input class="input" name="rate" type="number" min="0" step="0.01" required value="${esc(record?.rate??'')}"></div>`;if(type==='fabrication')fields+=`<div class="field"><label>Charge mode *</label><select class="select" name="charge_mode"><option value="none" ${(!record||record.charge_mode==='none')?'selected':''}>No extra charge</option><option value="per_piece" ${record?.charge_mode==='per_piece'?'selected':''}>Per piece</option><option value="per_sq_ft" ${record?.charge_mode==='per_sq_ft'?'selected':''}>Per sq ft</option><option value="flat_per_line" ${record?.charge_mode==='flat_per_line'?'selected':''}>Flat per job line</option></select></div><div class="field"><label>Charge amount (LKR) *</label><input class="input" name="rate" type="number" min="0" step="0.01" required value="${esc(record?.rate??0)}"></div>`;if(type==='other_item')fields+=`<div class="field"><label>Unit *</label><select class="select" name="unit">${['item','piece','sheet','set','roll','trip','job','sq ft'].map(unit=>`<option value="${esc(unit)}" ${(record?.unit||'item')===unit?'selected':''}>${esc(unit)}</option>`).join('')}</select></div><div class="field"><label>Default unit rate (LKR) *</label><input class="input" name="rate" type="number" min="0" step="0.01" required value="${esc(record?.rate??'')}"></div>`;if(type==='digital_particular')fields+=`<div class="field"><label>Billing unit</label><select class="select" name="unit">${['piece','sheet','set','pack','job'].map(unit=>`<option value="${unit}" ${(record?.unit||'piece')===unit?'selected':''}>${unit}</option>`).join('')}</select></div>`;if(record)fields+=`<div class="field"><label><input type="checkbox" name="is_active" ${record.is_active?'checked':''}> Active</label></div>`}openModal(`<div class="modal-head"><div><h3>${record?'Edit':'Add'} ${isRate?'Digital/Paper Price':esc(masterTypeLabel(type))}</h3><p>${isRate?'One exact price for a Particular + Media + Size + Side combination.':'Changes are saved in this workspace and used by new jobcards.'}</p></div><button class="close" data-action="close-modal">×</button></div><form id="jobcardMasterForm" data-kind="${isRate?'digital_rate':'master'}" data-type="${type}" data-id="${record?.id||''}"><div class="modal-body"><div id="jobcardMasterErrors" class="demo-flag" style="display:none"></div><div class="settings-form">${fields}</div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">${record?'Save changes':'Create'}</button></div></form>`)}
function jobcardSettingsPage(){const settings=businessSettings?.jobcard||jobcardSettings;const notice=businessSettingsError?`<div class="demo-flag">Could not load settings: ${esc(businessSettingsError)} <button data-action="refresh-jobcard-settings">Retry</button></div>`:businessSettingsLoading?'<div class="demo-flag">Loading saved jobcard settings…</div>':'<div class="live-flag">These settings are saved to this workspace and used by the jobcard wizard and pricing API.</div>';const canSave=businessSettingsLoaded&&!businessSettingsLoading&&!businessSettingsError;const nav=`<aside class="settings-nav">${settingTabs.map(item=>`<button class="${item==='Jobcards'?'active':''}" data-setting-tab="${esc(item)}">${esc(item)}</button>`).join('')}</aside>`;return `${head('Settings','Business, tax, sales, payments and Jobcard configuration for this workspace.',`<button class="btn primary" data-action="save-settings" ${canSave?'':'disabled'}>✓ Save settings</button>`)}${notice}<section class="card settings-layout">${nav}<div><div class="card-head"><div><h3>Jobcards</h3><p>Set the Flex dimension default and control Jobcard line-rate overrides.</p></div></div><div class="card-body"><div class="settings-form"><div class="field"><label>Default Flex dimension unit</label><select class="select" id="jobcardDefaultDimension"><option value="ft" ${settings.default_flex_dimension_unit==='ft'?'selected':''}>Feet</option><option value="in" ${settings.default_flex_dimension_unit==='in'?'selected':''}>Inches</option></select><small class="setting-hint">Each Flex line can still choose feet or inches; this is the initial value for a new line.</small></div><div class="field"><label><input type="checkbox" id="jobcardAllowRateOverride" ${settings.allow_rate_override?'checked':''}> Allow jobcard rate overrides</label><small class="setting-hint">If disabled, the API uses master rates only and rejects manual media, fabrication, Digital/Paper and Other Item rate changes.</small></div></div><div style="padding-top:15px"><button class="btn primary" data-action="save-settings" ${canSave?'':'disabled'}>Save changes</button></div></div></div></section>`}
async function saveJobcardSettings(){const dimension=$('#jobcardDefaultDimension')?.value||'ft',allowOverride=Boolean($('#jobcardAllowRateOverride')?.checked);try{const response=await apiRequest('/api/v1/settings',{method:'PATCH',body:JSON.stringify({category:'jobcard',settings:{default_flex_dimension_unit:dimension,allow_rate_override:allowOverride}})});businessSettings=response.data||{};businessSettingsLoaded=true;businessSettingsError='';jobcardSettings={...jobcardSettings,...(businessSettings.jobcard||{default_flex_dimension_unit:dimension,allow_rate_override:allowOverride})};jobcardMastersLoaded=false;toast('Jobcard settings saved for this workspace.');renderPage()}catch(error){toast(error.message)}}
const settingTabs=['Business','Tax','Product','Contact','Sale','POS','Display Screen','Purchases','Payment','Dashboard','Jobcards','System','Modules','Reward Points','Prefixes','Invoice','Receipt No','Payment No','Quotation No','Delivery Challan No','Journal','Contra Entry','Print Format','Backups','Database','Password Reset'];
function settingsPreviewPage(tab){if(tab==='Jobcards')return jobcardSettingsPage();const input=(label,value='',type='text',hint='')=>`<div class="field"><label>${esc(label)}</label><input class="input" type="${type}" value="${esc(value)}">${hint?`<small class="setting-hint">${esc(hint)}</small>`:''}</div>`;const select=(label,values,selected='')=>`<div class="field"><label>${esc(label)}</label><select class="select">${values.map(value=>`<option ${value===selected?'selected':''}>${esc(value)}</option>`).join('')}</select></div>`;const toggle=(label,checked=false,hint='')=>`<div class="field"><label><input type="checkbox" ${checked?'checked':''}> ${esc(label)}</label>${hint?`<small class="setting-hint">${esc(hint)}</small>`:''}</div>`;const section=(title,fields)=>`<div class="field full"><h4 style="font-size:10.8px;margin:4px 0;color:#58677a">${esc(title)}</h4></div>${fields.join('')}`;let fields=[];if(tab==='Business')fields=[section('Business profile',[input('Business Name','Print House'),input('Start Date','2026-01-01','date'),input('Default Profit Percent','25.00','number'),input('Phone'),input('Email'),input('Business Address'),input('Tax Registration Number'),select('Currency',['LKR · Sri Lankan Rupee','USD · US Dollar','Other ISO currency'],'LKR · Sri Lankan Rupee'),select('Currency Symbol Placement',['Before amount','After amount'],'Before amount'),select('Time Zone',['Asia/Colombo','UTC','Choose another timezone'],'Asia/Colombo'),select('Financial Year Start Month',['January','April','July'],'January'),select('Stock Accounting Method',['FIFO (First In First Out)','Weighted Average'],'FIFO (First In First Out)'),input('Transaction Edit Days','30','number'),select('Date Format',['dd/mm/yyyy','mm/dd/yyyy','yyyy-mm-dd'],'dd/mm/yyyy'),select('Time Format',['24 Hour','12 Hour'],'24 Hour'),select('Currency Precision',['0','1','2','3','4'],'2'),select('Quantity Precision',['0','1','2','3','4','5','6'],'2'),input('Upload Logo','', 'file')])];else if(tab==='Tax')fields=[section('Tax registration and inline tax',[input('Tax 1 Name','','text','For example, GSTIN or VAT registration label.'),input('Tax 1 No.'),input('Tax 2 Name','','text','Optional second registration label.'),input('Tax 2 No.'),toggle('Enable inline tax in purchase and sale',true)]),`<div class="field full"><a class="btn" data-page="taxes">Open separate Tax Rates &amp; Groups page →</a></div>`];else if(tab==='Product')fields=[section('Product configuration',[input('SKU Prefix','AS'),select('Enable Product Expiry',['Disabled','Add item expiry','Set expiry period'],'Disabled'),toggle('Enable Brands',true),toggle('Enable Categories',true),toggle('Enable Sub-Categories',true),toggle('Enable Price & Tax Info',true),select('Default Unit',['Please select','Piece','Meter'],'Please select'),toggle('Enable Sub Units'),toggle('Enable Racks'),toggle('Enable Row'),toggle('Enable Position'),toggle('Enable Warranty'),toggle('Product image required')])];else if(tab==='Contact')fields=[section('Contact defaults',[input('Default Credit Limit','','number','Applied to new customer contacts; can be overridden per contact.')])];else if(tab==='Sale')fields=[section('Sale defaults',[input('Default Sale Discount (%)','0','number'),select('Default Sale Tax',['None','Select tax group'],'None'),select('Sales Item Addition Method',['Increase item quantity if item already exists','Add as a new line'],'Increase item quantity if item already exists'),select('Amount Rounding Method',['None','Nearest whole unit','Nearest 5','Nearest 10','Always round up','Always round down'],'None'),toggle('Sale price is minimum selling price'),toggle('Allow Overselling'),toggle('Enable Sales Order'),toggle('Payment term required')]),section('Commission Agent',[select('Sales Commission Agent',['Disable','Enable'],'Disable'),select('Commission Calculation Type',['Invoice value','Paid amount','Profit'],'Invoice value'),toggle('Commission agent required'),input('Default commission rate (%)','0','number')])];else if(tab==='POS')fields=[section('Point of Sale workflow',[toggle('Express checkout',true),toggle('Allow creating customer at POS',true),toggle('Allow Walk-In Customer',true),toggle('Auto-print receipt'),toggle('Clear cart after final sale',true),toggle('Require named customer'),toggle('Auto-focus barcode scanner',true)])];else if(tab==='Display Screen')fields=[section('Product display',[toggle('Show product images',true),toggle('Show SKU',true),toggle('Show barcode'),toggle('Show stock quantity',true),toggle('Show selling price',true),select('Products per row',['2','3','4','5','6','8'],'4')])];else if(tab==='Purchases')fields=[section('Purchase workflow',[toggle('Allow editing product price from purchase screen',true),toggle('Enable Purchase Status',true),toggle('Enable Lot Number'),toggle('Enable Purchase Order'),toggle('Enable Purchase Requisition')])];else if(tab==='Payment')fields=[section('Payment methods and checkout',[toggle('Allow Cash',true),toggle('Allow Bank Transfer',true),toggle('Allow Card',true),toggle('Allow Cheque',true),toggle('Allow split / multiple payments',true),select('Default Payment Method',['Cash','Bank Transfer','Card','Cheque'],'Cash'),toggle('Enable Payment Links','','PayHere remains unavailable until verified gateway callbacks are configured.')])];else if(tab==='Dashboard')fields=[section('Dashboard display',[select('Default Date Range',['Today','Last 7 days','This month','Financial year'],'This month'),select('Auto Refresh',['Off','Every 15 seconds','Every 30 seconds','Every minute'],'Off'),toggle('Sales summary',true),toggle('Production status',true),toggle('Cash flow',true),toggle('Low-stock alerts',true),toggle('Due reminders',true),toggle('Recent activity',true)])];else if(tab==='System')fields=[section('Language and session preferences',[select('Default Language',['English','සිංහල','தமிழ்'],'English'),input('Automatic Logout (minutes)','60','number'),toggle('Show language selector',true)]),`<div class="field full"><div class="setting-hint">Database credentials, backups and payment-gateway secrets must be managed securely by the hosting administrator—not from tenant settings.</div></div>`];else if(tab==='Modules')fields=[section('Enable / Disable Modules',[toggle('Purchases',true),toggle('Add Sale',true),toggle('POS',true),toggle('Stock Transfers',true),toggle('Stock Adjustment',true),toggle('Expenses',true),toggle('Accounts',true),toggle('Tables'),toggle('Modifiers'),toggle('Service staff'),toggle('Bookings'),toggle('Kitchen'),toggle('Enable Subscription'),toggle('Types of service')])];else if(tab==='Reward Points')fields=[section('Earning Points Settings',[toggle('Enable Reward Points'),input('Reward Point Display Name','Points'),input('Amount Spend for One Point','1.00','number'),input('Minimum Order Total to Earn Reward','1.00','number'),input('Maximum Points per Order','','number')]),section('Redeem Points Settings',[input('Redeem Amount per Point','1.00','number'),input('Minimum Order Total to Redeem','1.00','number'),input('Minimum Redeem Points','','number'),input('Maximum Redeem Points per Order','','number'),input('Reward Expiry Period','','number'),select('Expiry Unit',['Days','Months','Years'],'Years')])];else if(tab==='Prefixes')fields=[section('Document number prefixes',[input('Purchase','PO'),input('Purchase Return','PR'),input('Purchase Requisition','PRQ'),input('Purchase Order','PO'),input('Stock Transfer','ST'),input('Stock Adjustment','SA'),input('Sell Return','CN'),input('Expenses','EP'),input('Contacts','CO'),input('Purchase Payment','PP'),input('Sell Payment','SP'),input('Expense Payment','EPM'),input('Business Location','BL'),input('Username','USR'),input('Subscription No.','SUB'),input('Draft','DRAFT-'),input('Sales Order','SO')])];else fields=[section(tab+' numbering',[input(tab+' Prefix','INV-'),input('Next Number','1','number'),select('Number Padding',['4 digits','5 digits','6 digits'],'6 digits'),select('Reset Sequence',['Never','Every financial year','Every year'],'Never')])];const inner=fields.map(item=>typeof item==='string'?item:`<div class="settings-form">${item}</div>`).join('');return `${head('Settings','Business, tax, sales, products, payments and workflow options for this workspace.',`<button class="btn primary" data-action="save-settings">✓ Save settings</button>`)}<div class="demo-flag">This settings prototype is for interface preview; the authenticated Laravel settings page saves tenant-scoped values through the API. Some module behavior is still under development.</div><section class="card settings-layout"><aside class="settings-nav">${settingTabs.map(item=>`<button class="${item===tab?'active':''}" data-setting-tab="${esc(item)}">${esc(item)}</button>`).join('')}</aside><div><div class="card-head"><div><h3>${esc(tab)}</h3><p>Customize ${esc(tab.toLowerCase())} preferences for this business.</p></div></div><div class="card-body">${inner}</div><div style="padding:0 15px 15px"><button class="btn primary" data-action="save-settings">Save changes</button></div></div></section>`}
