}[id];const [title,sub,headers,rows]=cfg;const data=rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]])));return `${head(title,sub,`<button class="btn" data-action="export">↓ Export</button><button class="btn primary" data-action="generic-add">＋ New entry</button>`)}<section class="card table-card"><div class="card-head"><div><h3>${esc(title)}</h3><p>Period: 01 Aug 2026 – 01 Sep 2026</p></div><div class="toolbar"><input class="input" type="date" value="2026-08-01"><input class="input" type="date" value="2026-09-01"><button class="btn ghost" data-action="filter">Apply</button></div></div>${tableHtml(headers.map(h=>({label:h,key:h})),data)}</section>`}
