<div class="steps">${steps.map(([name,n],i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${newJobStep===n?'active':newJobStep>n?'done':''}"><span class="step-circle">${newJobStep>n?'✓':n}</span><span>${esc(tr(name))}</span></div>`).join('')}</div>
<section class="card wizard-card">${newJobStep===1?renderCustomerStep():newJobStep===2?renderItemsStep():renderBillingStep()}</section>
<div class="wizard-nav"><button class="btn" data-action="cancel-job">Cancel</button><div class="actions">${newJobStep>1?`<button class="btn" data-action="job-prev">← ${esc(tr('Previous'))}</button>`:''}${newJobStep<3?`<button class="btn primary" data-action="job-next">${esc(tr('Next'))} →</button>`:`<button class="btn good" data-action="save-job">✓ ${esc(tr('Save Jobcard'))}</button>`}</div></div>
<div class="demo-note">Job number and totals are generated by Laravel · an invoice is created with the jobcard · any advance is recorded as a payment receipt · WhatsApp messaging still requires provider setup</div>`}
function renderCustomerOutstanding(selected){
 if(!selected)return '<div class="outstanding-empty">Select a customer to view previous bill balances.</div>';
 const statement=customerOutstandingById[String(selected.id)];
 if(!statement||statement.loading)return '<div class="outstanding-empty">Loading previous bill balances…</div>';
 if(statement.error)return `<div class="outstanding-error">Outstanding invoices could not be loaded: ${esc(statement.error)}<br><button type="button" data-action="refresh-customer-outstanding" data-customer-id="${esc(selected.id)}">Retry</button></div>`;
 const invoices=Array.isArray(statement.invoices)?statement.invoices:[];
 const openingDue=Number(statement.opening_amount_due||0);
 const rows=[];
 if(openingDue>0)rows.push(`<div class="outstanding-table"><span>—</span><span class="outstanding-invoice-ref"><strong>Opening balance</strong><small>Contact opening balance</small></span><span>${money(openingDue)}</span></div>`);
 rows.push(...invoices.map(invoice=>`<div class="outstanding-table"><span>${esc(displayDate(invoice.issued_at))}</span><span class="outstanding-invoice-ref"><strong>${esc(invoice.invoice_number||'—')}</strong><small>${esc(invoice.status||'Outstanding')}</small></span><span>${money(invoice.balance)}</span></div>`));
 if(!rows.length)return `<div class="outstanding-empty">No outstanding invoices for ${esc(selected.name)}.</div>`;
 const total=Number(statement.outstanding_total??(openingDue+invoices.reduce((sum,invoice)=>sum+Number(invoice.balance||0),0)));
 return `<div class="outstanding-summary"><span>Total outstanding</span><strong>${money(total)}</strong></div><div class="outstanding-table outstanding-header"><span>Date</span><span>Bill / Invoice</span><span>Balance</span></div>${rows.join('')}${Number(statement.remaining_invoice_count||0)>0?`<div class="outstanding-more">+ ${Number(statement.remaining_invoice_count)} older outstanding invoice(s), included in total.</div>`:''}`
}
function renderCustomerStep(){const selected=findJobCustomer(draft.customerId);return `${customersError?`<div class="demo-flag">Customers could not be loaded: ${esc(customersError)} <button data-action="refresh-customers">Retry</button></div>`:''}${walkInError?`<div class="demo-flag">Walk-In Customer could not be loaded: ${esc(walkInError)} <button data-action="refresh-customers">Retry</button></div>`:''}${!customersError&&!walkInError&&((customersLoading&&!customersLoaded)||(walkInLoading&&!walkInLoaded))?'<div class="demo-flag">Loading workspace customers…</div>':''}<div class="wizard-section-title">Step 1: Customer Information</div><div class="customer-step"><div class="customer-fields"><div class="field wide"><label>Select Customer *</label><div class="customer-control"><select class="select" data-draft="customerId"><option value="">Choose a customer…</option>${jobCustomerOptions().map(c=>`<option value="${c.id}" ${String(c.id)===String(draft.customerId)?'selected':''}>${esc(c.name)}${c.is_default?' · '+esc(tr('Walk-In (full payment)')):''}${c.phone?' · '+esc(c.phone):''}</option>`).join('')}</select><button class="square-add" data-action="add-customer" title="Add customer">＋</button></div>${selected?.is_default?`<div class="walkin-note">${esc(tr('Walk-In Customer: full payment is required. Create/select a named customer for a due balance.'))}</div>`:''}</div><div class="field"><label>Order By Name</label><input class="input" data-draft="orderBy" value="${esc(draft.orderBy||selected?.name||'')}"></div><div class="field"><label>Mobile Number *</label><input class="input" data-draft="phone" value="${esc(draft.phone||selected?.phone||'')}"></div><div class="field wide"><label>WhatsApp Number</label><input class="input" data-draft="whatsapp" value="${esc(draft.whatsapp||selected?.whatsapp||'')}"></div></div><div class="field"><label>Job Date</label><input class="input" type="date" data-draft="date" value="${esc(draft.date)}"><label style="margin-top:4px">Delivery Date *</label><input class="input" type="date" data-draft="due" value="${esc(draft.due)}"></div><div class="outstanding-wrap"><label style="display:block;font-size:10px;font-weight:800;margin:3px 0 6px">Previous Bill Details (Outstanding)</label><div class="outstanding-box">${renderCustomerOutstanding(selected)}</div></div></div>`}
function optionsFor(field,value='',category=''){if(field==='dimension_unit')return `<option value="ft" ${value==='ft'?'selected':''}>Feet</option><option value="in" ${value==='in'?'selected':''}>Inches</option>`;const masterType=field==='media_id'?(category==='flex'?'flex_media':'digital_media'):field==='fabrication_id'?'fabrication':field==='particular_id'?'digital_particular':field==='size_id'?'digital_size':field==='side_id'?'digital_side':field==='other_item_id'?'other_item':null;if(masterType)return jobcardMasterOptions(masterType,value);return '<option value="">Select…</option>'}
function itemInput(category,index,[key,label,type],item){const value=item[key]??'';if(type==='readonly'){const result=lineTotal(category,item),display=key==='area'?result.area.toFixed(2):key==='total'?money(result.total):value||'0.00';return `<td class="calc-cell" data-calc="${key}" data-index="${index}">${esc(display)}</td>`}if(type==='select')return `<td><select data-line="${category}" data-index="${index}" data-field="${key}">${optionsFor(key,value,category)}</select></td>`;const wide=['remark','size'].includes(key),dim=['w','h','bw','bh'].includes(key),min=dim||key==='qty'?'0.01':'0',inputType=type==='text'?'text':'number',inputAttrs=inputType==='number'?`min="${min}" step="0.01"`:`maxlength="120"`;return `<td><input class="${wide?'item-wide':''}" type="${inputType}" ${inputAttrs} ${['rate','fabrication_rate'].includes(key)&&!jobcardSettings.allow_rate_override?'disabled':''} placeholder="${esc(label)}" value="${esc(value)}" data-line="${category}" data-index="${index}" data-field="${key}"></td>`}
function renderItemsStep(){const category=jobTab,rows=draft.items[category]||[],schema=itemSchemas[category];const notice=jobcardMastersError?`<div class="demo-flag">Jobcard masters could not be loaded: ${esc(jobcardMastersError)} <button data-action="refresh-jobcard-masters">Retry</button></div>`:jobcardMastersLoading?'<div class="demo-flag">Loading your workspace media, fabrication and pricing masters…</div>':'';const instruction=category==='flex'?'W/H are the production/job-sheet dimensions and auto-fill Billing W/H. Billing W/H determine the billable sq ft area and can be adjusted separately; the fabrication charge is added. Rate overrides depend on Jobcard Settings.':category==='digital'?'Choose a master price by Particular + Media + Size + Side. You may override the unit rate if Jobcard Settings allow it.':'Choose an Other Item master; total is quantity × its default or overridden unit rate.';return `${notice}<div class="item-tabs"><button class="item-tab ${category==='flex'?'active':''}" data-item-tab="flex">${esc(tr('Flex Items'))}<span class="tab-count">${draft.items.flex.length}</span></button><button class="item-tab ${category==='digital'?'active':''}" data-item-tab="digital">${esc(tr('Digital/Paper Items'))}<span class="tab-count">${draft.items.digital.length}</span></button><button class="item-tab ${category==='other'?'active':''}" data-item-tab="other">${esc(tr('Other Items'))}<span class="tab-count">${draft.items.other.length}</span></button><div class="item-toolbar"><button class="btn sm" data-page="jobcard-masters">⚙ Masters &amp; rates</button><button class="btn cyan sm" data-action="add-item">＋ ${esc(tr('Add Item'))}</button></div></div><div class="items-scroll"><table class="items-table"><thead><tr>${schema.map(s=>`<th>${esc(s[1])}</th>`).join('')}<th>#</th></tr></thead><tbody>${rows.length?rows.map((item,index)=>`<tr>${schema.map(s=>itemInput(category,index,s,item)).join('')}<td><button class="item-remove" data-action="remove-item" data-index="${index}" data-category="${category}">×</button></td></tr>`).join(''):`<tr><td colspan="${schema.length+1}" class="empty">No ${category==='flex'?'flex':category==='digital'?'digital/paper':'other'} items yet. Choose “Add Item” to start this line.</td></tr>`}</tbody></table></div><div style="display:flex;justify-content:space-between;align-items:center;padding:11px 14px;gap:12px"><span class="task-note">${esc(instruction)}</span><b style="font-size:10.8px;white-space:nowrap">Current subtotal: <span id="itemsSubtotal">${money(draftSubtotal())}</span></b></div>`}
function round2(value){return Math.round((Number(value||0)+Number.EPSILON)*100)/100}
function matchedDigitalRate(item){return (jobcardMasters.digital_rates||[]).find(r=>r.is_active&&String(r.particular_id)===String(item.particular_id)&&String(r.media_id)===String(item.media_id)&&String(r.size_id)===String(item.size_id)&&String(r.side_id)===String(item.side_id))||null}
function lineUnitRate(cat,item){if(String(item.rate??'').trim()!=='')return round2(item.rate);if(cat==='flex')return round2(jobcardMasterById('flex_media',item.media_id)?.rate||0);if(cat==='digital')return round2(matchedDigitalRate(item)?.rate||0);if(cat==='other')return round2(jobcardMasterById('other_item',item.other_item_id)?.rate||0);return 0}
function fabricationCharge(item,billableArea,pieces){const fabrication=jobcardMasterById('fabrication',item.fabrication_id);if(!fabrication)return 0;const rate=item.fabrication_rate_override?Number(item.fabrication_rate||0):Number(fabrication.rate||0);if(fabrication.charge_mode==='per_piece')return round2(rate*pieces);if(fabrication.charge_mode==='per_sq_ft')return round2(rate*billableArea);if(fabrication.charge_mode==='flat_per_line')return round2(rate);return 0}
function lineTotal(cat,item){const qty=Number(item.qty||0),rate=lineUnitRate(cat,item);if(cat==='flex'){const w=Number(item.bw||item.w||0),h=Number(item.bh||item.h||0),unit=item.dimension_unit||jobcardSettings.default_flex_dimension_unit||'ft';const areaEach=w*h*(unit==='in'?1/144:1),area=round2(areaEach*qty);return {area,total:round2(area*rate+fabricationCharge(item,area,qty))}}return {area:0,total:round2(round2(qty)*rate)}}
function draftSubtotal(){let sum=0;for(const cat of Object.keys(draft.items))for(const item of draft.items[cat])sum+=lineTotal(cat,item).total;return Math.round(sum*100)/100}
function refreshItemTotals(){document.querySelectorAll('[data-calc="total"]').forEach(el=>{const item=draft.items[el.closest('tr')?.querySelector('[data-line]')?.dataset.line]?.[Number(el.dataset.index)];if(item)el.textContent=money(lineTotal(el.closest('tr').querySelector('[data-line]').dataset.line,item).total)});document.querySelectorAll('[data-calc="area"]').forEach(el=>{const cat=el.closest('tr')?.querySelector('[data-line]')?.dataset.line;const item=draft.items[cat]?.[Number(el.dataset.index)];if(item)el.textContent=lineTotal(cat,item).area.toFixed(2)});const sub=$('#itemsSubtotal');if(sub)sub.textContent=money(draftSubtotal());const bill=$('#billingSubtotal');if(bill)updateBillingNumbers()}
function renderBillingStep(){
 const walkIn=isWalkInCustomer();
 if(walkIn)draft.advance=round2(finalBill());
 const hours=Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0')).map(hour=>`<option value="${hour}" ${String(draft.dueHour)===hour?'selected':''}>${hour}</option>`).join('');
 const minutes=Array.from({length:12},(_,i)=>String(i*5).padStart(2,'0')).map(minute=>`<option value="${minute}" ${String(draft.dueMinute)===minute?'selected':''}>${minute}</option>`).join('');
 const modes=[['cash','Cash'],['bank_transfer','Bank Transfer'],['card_manual','Card'],['cheque','Cheque']].map(([value,label])=>`<option value="${value}" ${draft.paymentMode===value?'selected':''}>${label}</option>`).join('');
 const accounts=jobcardPaymentMethods.map(method=>{const displayName=method.method_type==='cash'&&String(method.name).trim().toLowerCase()==='cash'?'Cash in Hand':method.name;return `<option value="${esc(method.id)}" ${String(draft.paymentMethodId)===String(method.id)?'selected':''}>${esc(displayName)}${method.location_id?' · '+esc(method.code):''}</option>`}).join('');
 const masterNotice=jobcardMastersLoading?'<div class="billing-help">Loading this workspace’s deposit accounts…</div>':jobcardMastersError?`<div class="billing-help error">Deposit account list could not be loaded: ${esc(jobcardMastersError)}</div>`:jobcardPaymentMethods.length?'': '<div class="billing-help error">No active deposit account is configured. Add one in workspace setup before recording an advance.</div>';
 const walkInNotice=walkIn?`<div class="billing-help error">${esc(tr('Walk-In Customer orders must be paid in full. Create or select a named customer to leave an amount due.'))}</div>`:'';
 return `<div class="wizard-section-title">Step 3: ${esc(tr('Billing & Finalization'))}</div><div class="billing-grid"><section class="billing-summary"><div class="billing-section-label">${esc(tr('Billing Summary'))}</div><div class="summary-rows"><div class="sum-row"><span>${esc(tr('Total Bill'))}</span><strong id="billingTotalBill">${money(draftSubtotal())}</strong></div><div class="sum-row"><span>${esc(tr('Discount'))}</span><input class="input billing-number" type="number" min="0" step="0.01" data-draft="discount" value="${esc(draft.discount)}" aria-label="Discount"></div><div class="sum-row"><span>${esc(tr('Sub Total'))}</span><strong id="billingSubtotal">${money(discountedSubtotal())}</strong></div><div class="sum-row"><span>${esc(tr('Round Off'))}</span><div class="roundoff-control"><input class="input billing-number" type="number" step="0.01" data-draft="roundOff" value="${esc(draft.roundOff)}" aria-label="Round off" ${draft.roundOffEnabled?'':'disabled'}><label title="Apply round-off"><input type="checkbox" data-draft="roundOffEnabled" ${draft.roundOffEnabled?'checked':''}><span class="sr-only">Apply round-off</span></label></div></div><div class="sum-row final"><span>${esc(tr('Final Bill'))}</span><strong id="billingFinal">${money(finalBill())}</strong></div><div class="sum-row advance"><span>${esc(tr('Advance Received'))}</span><strong id="billingAdvance">${money(draft.advance)}</strong></div></div><div class="sum-row balance"><span>${esc(tr('Outstanding Balance'))}</span><strong id="billingBalance">${money(balanceDue())}</strong></div></section><section class="billing-side"><div class="payment-box"><h4>${esc(tr('Receive Advance & Generate Receipt'))}</h4><div class="billing-fields"><div class="field"><label>${walkIn?esc(tr('Full Payment (Walk-In Customer)')):esc(tr('Advance Received'))}</label><input class="input" type="number" min="0" max="${esc(finalBill())}" step="0.01" data-draft="advance" value="${esc(draft.advance)}" placeholder="0.00" ${walkIn?'disabled':''}></div><div class="field"><label>${esc(tr('Payment Mode'))}</label><select class="select" data-draft="paymentMode">${modes}</select></div><div class="field"><label>${esc(tr('Deposit Account'))}</label><select class="select" data-draft="paymentMethodId" ${jobcardPaymentMethods.length?'':'disabled'}>${accounts||'<option value="">No deposit accounts configured</option>'}</select></div><div class="field"><label>${esc(tr('Reference No.'))}</label><input class="input" data-draft="paymentReference" maxlength="120" value="${esc(draft.paymentReference)}" placeholder="UPI / cheque / transaction reference"></div></div>${walkInNotice}${masterNotice}</div><div class="billing-fields billing-details"><div class="field full"><label>${esc(tr('Comment'))}</label><textarea class="textarea billing-comment" data-draft="comment" maxlength="5000" placeholder="Add any jobcard comments here…">${esc(draft.comment)}</textarea></div><label class="billing-check whatsapp-check"><input type="checkbox" data-draft="sendWhatsapp" ${draft.sendWhatsapp?'checked':''}><span>${esc(tr('Send WhatsApp'))}</span></label><div class="billing-help full">${esc(tr('WhatsApp sending is not connected yet; this option will not send a message in this build.'))}</div><div class="field"><label>${esc(tr('Delivery Date'))} *</label><input class="input" type="date" data-draft="due" value="${esc(draft.due)}"></div><div class="field"><label>${esc(tr('Delivery Time'))} *</label><div class="delivery-time"><select class="select" data-draft="dueHour" aria-label="Delivery hour">${hours}</select><select class="select" data-draft="dueMinute" aria-label="Delivery minute">${minutes}</select><select class="select" data-draft="dueMeridiem" aria-label="AM or PM"><option value="AM" ${draft.dueMeridiem==='AM'?'selected':''}>AM</option><option value="PM" ${draft.dueMeridiem==='PM'?'selected':''}>PM</option></select></div></div><div class="invoice-auto full"><label class="billing-check"><input type="checkbox" checked disabled><span>${esc(tr('Generate Invoice for this Jobcard'))}</span></label><small>${esc(tr('Invoice will always be generated automatically for this jobcard.'))}</small></div></div></section></div>`
}
function discountedSubtotal(){return Math.max(0,draftSubtotal()-Number(draft.discount||0))}
function finalBill(){return Math.max(0,discountedSubtotal()+(draft.roundOffEnabled?Number(draft.roundOff||0):0))}
function balanceDue(){return Math.max(0,finalBill()-Number(draft.advance||0))}
function dueTime24(){const hour12=Number(draft.dueHour||7)%12;const hour24=hour12+(draft.dueMeridiem==='PM'?12:0);return `${String(hour24).padStart(2,'0')}:${String(Number(draft.dueMinute||0)).padStart(2,'0')}`}
function updateBillingNumbers(){const walkIn=isWalkInCustomer();if(walkIn)draft.advance=round2(finalBill());const advanceInput=$('[data-draft="advance"]');if(advanceInput){advanceInput.disabled=walkIn;if(walkIn)advanceInput.value=String(draft.advance)}for(const [id,val] of [['billingTotalBill',draftSubtotal()],['billingSubtotal',discountedSubtotal()],['billingFinal',finalBill()],['billingAdvance',Number(draft.advance||0)],['billingBalance',balanceDue()]]){const el=$('#'+id);if(el)el.textContent=money(val)}}
function customerModal(customerId=null){const contact=customers.find(c=>String(c.id)===String(customerId));const isBoth=Boolean(contact?.is_customer&&contact?.is_supplier);const kind=isBoth?'both':contact?.is_supplier?'supplier':'customer';openModal(`<div class="modal-head"><div><h3>${contact?'Edit Contact':'Add Customer'}</h3><p>${contact?'Changes are saved to this workspace.':'Create a customer/supplier record in this workspace.'}</p></div><button class="close" data-action="close-modal">×</button></div><form id="customerForm" data-customer-id="${contact?.id||''}"><div class="modal-body"><div id="customerFormErrors" class="demo-flag" style="display:none"></div><div class="settings-form"><div class="field"><label>Contact name *</label><input class="input" name="name" required maxlength="160" value="${esc(contact?.name||'')}"></div><div class="field"><label>Contact type</label><select class="select" name="type"><option value="customer" ${kind==='customer'?'selected':''}>Customer</option><option value="supplier" ${kind==='supplier'?'selected':''}>Supplier</option><option value="both" ${kind==='both'?'selected':''}>Customer &amp; supplier</option></select></div><div class="field"><label>Contact code</label><input class="input" name="contact_code" maxlength="40" value="${esc(contact?.contact_code||'')}"></div><div class="field"><label>Mobile number</label><input class="input" name="phone" maxlength="30" value="${esc(contact?.phone||'')}"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" maxlength="190" value="${esc(contact?.email||'')}"></div><div class="field"><label>Credit limit (LKR)</label><input class="input" type="number" name="credit_limit" min="0" step="0.01" value="${contact?.credit_limit??''}"></div><div class="field"><label>Payment terms (days)</label><input class="input" type="number" name="payment_term_days" min="0" max="3650" step="1" value="${contact?.payment_term_days??0}"></div><div class="field full"><label>Billing address</label><textarea class="textarea" name="billing_address" maxlength="3000">${esc(contact?.billing_address||'')}</textarea></div><div class="field full"><label>Notes</label><textarea class="textarea" name="notes" maxlength="5000">${esc(contact?.notes||'')}</textarea></div></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">${contact?'Save changes':'Add contact'}</button></div></form>`)}
function transactionModal(kind){const isReceipt=kind==='receipt',title=isReceipt?'Receive Customer Receipt':'Record Payment';openModal(`<div class="modal-head"><div><h3>${title}</h3><p>${isReceipt?'Record a customer receipt against an invoice.':'Record a payment made to a supplier or expense.'}</p></div><button class="close" data-action="close-modal">×</button></div><form id="transactionForm" data-kind="${kind}"><div class="modal-body"><div class="settings-form"><div class="field"><label>${isReceipt?'Customer':'Payee'} *</label><select class="select" name="party" required><option value="">Select…</option>${(isReceipt?customers.map(c=>c.name):['Lanka Paper Traders','Flex Supply Co.','Ink House','Other']).map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Amount (LKR) *</label><input class="input" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Payment mode</label><select class="select" name="mode"><option>Cash</option><option>Bank transfer</option><option>Card</option><option>Cheque</option></select></div><div class="field"><label>Reference / Invoice No.</label><input class="input" name="reference" placeholder="e.g. INV-2408"></div><div class="field full"><label>Note</label><input class="input" name="note" placeholder="Optional remark"></div></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">${isReceipt?'Save receipt':'Save payment'}</button></div></form>`)}
function paymentReceiptsLoadingModal(order){return `<div class="modal-head"><div><h3>Payment Receipts</h3><p>Job No: ${esc(order.job_number||order.ref||'—')}</p></div><button class="close" data-action="close-modal" aria-label="Close payment receipts">×</button></div><div class="modal-body"><div class="payment-total">Loading receipt history…</div><div class="empty">Retrieving saved payments from the workspace.</div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Close</button></div>`}
function paymentReceiptsErrorModal(order,error){return `<div class="modal-head"><div><h3>Payment Receipts</h3><p>Job No: ${esc(order.job_number||order.ref||'—')}</p></div><button class="close" data-action="close-modal" aria-label="Close payment receipts">×</button></div><div class="modal-body"><div class="demo-flag">Receipts could not be loaded: ${esc(error.message)} <button data-action="show-payment-receipts" data-order-id="${esc(order.id)}">Retry</button></div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Close</button></div>`}
function paymentReceiptsModal(order){
 const invoices=Array.isArray(order.invoices)?order.invoices:[];
 const payments=invoices.flatMap(invoice=>(Array.isArray(invoice.payments)?invoice.payments:[]).map(payment=>({...payment,paymentDate:payment.paid_at||payment.created_at}))).sort((a,b)=>new Date(b.paymentDate||0)-new Date(a.paymentDate||0));
 const totalPaid=Number(order.paidAmount??invoices.reduce((sum,invoice)=>sum+Number(invoice.paid_total||0),0));
 const modeLabel=method=>({cash:'Cash',bank_transfer:'Bank transfer',card_manual:'Card',cheque:'Cheque'}[String(method||'').toLowerCase()]||String(method||'—').replaceAll('_',' ').replace(/^./,letter=>letter.toUpperCase()));
 const rows=payments.map(payment=>{const succeeded=payment.status==='succeeded',status= succeeded?'Active':String(payment.status||'Pending').replace(/^./,letter=>letter.toUpperCase()),statusClass=succeeded?'succeeded':String(payment.status||'pending').toLowerCase().includes('fail')?'failed':'pending';return `<tr><td>${esc(displayDate(payment.paymentDate))}</td><td>${esc(displayTime(payment.paymentDate))}</td><td>${esc(payment.receipt_number||'—')}</td><td class="receipt-amount">${money(payment.amount)}</td><td>${esc(modeLabel(payment.method))}</td><td><span class="payment-receipt-state ${statusClass}">${esc(status)}</span></td><td>${esc(payment.approver?.name||'—')}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No payment receipts recorded for this job.</td></tr>';
 return `<div class="modal-head"><div><h3>Payment Receipts</h3><p>Job No: ${esc(order.job_number||order.ref||'—')}</p></div><button class="close" data-action="close-modal" aria-label="Close payment receipts">×</button></div><div class="modal-body"><div class="payment-total">Total Paid: ${money(totalPaid)}</div><div class="table-wrap"><table class="payment-receipts-table"><thead><tr><th>Receipt Date</th><th>Receipt Time</th><th>Receipt No</th><th>Amount</th><th>Mode</th><th>Status</th><th>Created By</th></tr></thead><tbody>${rows}</tbody></table></div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Close</button></div>`
}
async function showPaymentReceipts(orderId){
 const order=jobs.find(item=>String(item.id)===String(orderId));
 if(!order){toast('Payment receipt details could not be found. Refresh the Job Cards list and try again.');return}
 const requestId=++paymentReceiptsRequestId;
 openModal(paymentReceiptsLoadingModal(order),'payment-receipts');
 try{const savedOrder=await apiRequest(`/api/v1/orders/${encodeURIComponent(orderId)}`);if(requestId!==paymentReceiptsRequestId)return;openModal(paymentReceiptsModal(normalizeOrder(savedOrder)),'payment-receipts')}
 catch(error){if(requestId===paymentReceiptsRequestId)openModal(paymentReceiptsErrorModal(order,error),'payment-receipts')}
}
function orderDetailsModal(order){
 const itemRows=(order.items||[]).map(item=>`<tr><td>${esc(item.description)}</td><td>${esc(item.quantity)} ${esc(item.unit||'')}</td><td>${money(item.unit_price)}</td><td>${money(item.line_total)}</td></tr>`).join('');
 const eventRows=(order.events||[]).map(event=>`<div class="order-event"><div><strong>${esc(orderStageLabel(event.to_stage))}</strong><span>${esc(displayDateTime(event.created_at))} · ${esc(event.changed_by?.name||'Workspace user')}</span>${event.note?`<p>${esc(event.note)}</p>`:''}</div></div>`).join('');
 const invoiceRows=(order.invoices||[]).map(invoice=>{const receiptList=(invoice.payments||[]).map(payment=>`${esc(payment.receipt_number||`RCP-${String(payment.id).padStart(6,'0')}`)} · ${money(payment.amount)} · ${esc(payment.method)}`).join('<br>')||'—';return `<tr><td>${esc(invoice.invoice_number)}</td><td>${money(invoice.total)}</td><td>${money(invoice.paid_total)}</td><td>${esc(invoice.status)}</td><td>${receiptList}</td></tr>`}).join('');
 return `<div class="modal-head"><div><h3>${esc(order.ref||order.job_number)} · ${esc(order.subject||order.title)}</h3><p>${esc(order.customer?.name||order.customer||'')} · ${esc(order.contact_phone||order.contact||'')}</p></div><button class="close" data-action="close-modal">×</button></div><div class="modal-body"><div class="live-flag">${esc(orderStageLabel(order.production_stage))} · ${money(order.total||order.amount)} · due ${esc(displayDate(order.due_at))}</div><div class="settings-form"><div class="field"><label>Job number</label><div>${esc(order.job_number||order.ref)}</div></div><div class="field"><label>Customer</label><div>${esc(order.customer?.name||order.customer||'—')}</div></div><div class="field"><label>Order by</label><div>${esc(order.contact_name||'—')}</div></div><div class="field"><label>Mobile / WhatsApp</label><div>${esc(order.contact_phone||'—')} · ${esc(order.whatsapp_phone||'—')}</div></div><div class="field"><label>Job date</label><div>${esc(displayDate(order.job_date||order.created_at))}</div></div><div class="field"><label>Due date</label><div>${esc(displayDateTime(order.due_at))}</div></div><div class="field"><label>Priority</label><div>${esc(order.priority||'normal')}</div></div><div class="field"><label>Production stage</label><div>${esc(orderStageLabel(order.production_stage))}</div></div></div>${invoiceRows?`<h4 style="font-size:12px;margin:17px 0 7px">Billing &amp; receipts</h4><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Total</th><th>Paid</th><th>Status</th><th>Payment receipt</th></tr></thead><tbody>${invoiceRows}</tbody></table></div>`:''}<h4 style="font-size:12px;margin:17px 0 7px">Job items</h4>${itemRows?`<div class="table-wrap"><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit rate</th><th>Line total</th></tr></thead><tbody>${itemRows}</tbody></table></div>`:'<div class="empty">No item details.</div>'}<h4 style="font-size:12px;margin:17px 0 7px">Production history</h4><div class="order-events">${eventRows||'<div class="empty">No stage events recorded.</div>'}</div>${order.notes?`<div class="setting-hint" style="margin-top:12px"><strong>Job notes:</strong> ${esc(order.notes)}</div>`:''}${canManageProduction&&((ORDER_TRANSITIONS[order.production_stage]||[]).length)?`<div class="order-stage-editor"><div class="field"><label>Stage update note (optional)</label><input class="input" data-stage-note maxlength="2000" placeholder="e.g. Proof approved by customer"></div>${productionStageControls(order)}</div>`:''}</div><div class="modal-foot"><a class="btn primary" href="/orders/${encodeURIComponent(order.id)}/job-sheet" target="_blank" rel="noopener">▤ Print Job Card</a><button class="btn" data-action="close-modal">Close</button></div>`
}
async function showOrderDetails(orderId){activeOrderModalId=Number(orderId);openModal('<div class="modal-head"><div><h3>Loading jobcard…</h3><p>Retrieving saved items and production history.</p></div><button class="close" data-action="close-modal">×</button></div><div class="modal-body"><div class="empty">Loading from the workspace database…</div></div>');try{const order=await apiRequest(`/api/v1/orders/${encodeURIComponent(orderId)}`);if(activeOrderModalId===Number(orderId))openModal(orderDetailsModal(normalizeOrder(order)))}catch(error){if(activeOrderModalId===Number(orderId))openModal(`<div class="modal-head"><div><h3>Could not load jobcard</h3></div><button class="close" data-action="close-modal">×</button></div><div class="modal-body"><div class="demo-flag">${esc(error.message)}</div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Close</button></div>`);else toast(error.message)}}
async function moveOrderStage(orderId,stage,note=''){if(!canManageProduction){toast('Your workspace role cannot move production stages.');return}if(!stage){toast('Choose a target production stage first.');return}if(stageSavingIds.has(Number(orderId)))return;stageSavingIds.add(Number(orderId));try{const updated=await apiRequest(`/api/v1/orders/${encodeURIComponent(orderId)}/stage`,{method:'PATCH',body:JSON.stringify({stage,note:note||null})});const normalized=normalizeOrder(updated);jobs=jobs.map(order=>Number(order.id)===Number(orderId)?normalized:order);if(activeOrderModalId===Number(orderId))openModal(orderDetailsModal(normalized));toast(`Job ${normalized.ref} moved to ${orderStageLabel(stage)}.`);loadOrders({force:true,quiet:true,pageNumber:ordersCurrentPage,search:ordersSearch,status:ordersStatus});loadDashboardSummary({force:true,quiet:true})}catch(error){toast(error.message)}finally{stageSavingIds.delete(Number(orderId))}}
function openModal(html,variant=''){if(variant!=='payment-receipts')paymentReceiptsRequestId++;const modal=$('#modal');modal.classList.toggle('payment-receipts-modal',variant==='payment-receipts');modal.innerHTML=html;$('#backdrop').classList.add('open');document.body.style.overflow='hidden';$('#modal input')?.focus()}
function closeModal(){activeOrderModalId=null;paymentReceiptsRequestId++;$('#modal').classList.remove('payment-receipts-modal');$('#backdrop').classList.remove('open');document.body.style.overflow=''}
function renderPage(){if((page==='customers'||page==='new-job')&&!customersLoaded&&!customersLoading)loadCustomers({quiet:true});if(page==='new-job'&&(newJobStep===2||newJobStep===3)&&!jobcardMastersLoaded&&!jobcardMastersLoading)loadJobcardMasters({quiet:true});if(page==='jobcard-masters'&&!jobcardMastersLoaded&&!jobcardMastersLoading)loadJobcardMasters({quiet:true});if(page==='settings'&&settingsTab==='Jobcards'&&!businessSettingsLoaded&&!businessSettingsLoading)loadBusinessSettings({quiet:true});if(ORDER_DATA_PAGES.has(page)&&!ordersLoaded&&!ordersLoading)loadOrders({quiet:true});if(page==='dashboard'&&!dashboardSummary&&!dashboardLoading)loadDashboardSummary({quiet:true});let html='';if(page==='dashboard')html=dashboard();else if(page==='new-job')html=newJobPage();else if(page==='job-status')html=statusBoard();else if(page==='jobcard-masters')html=jobcardMasterPage();else if(page==='reports')html=reportsPage();else if(page==='taxes')html=taxPage();else if(page==='settings')html=settingsPage();else if(page==='master-data')html=masterDataPage();else html=genericList(page);$('#content').innerHTML=html;$('#nav').innerHTML=navHtml();$('#crumb').textContent=pageName(page);document.documentElement.lang=lang;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function startJob(){
 if(!canCreateOrders){toast('Your workspace role cannot create jobcards.');return}
 const dueDate=new Date();dueDate.setDate(dueDate.getDate()+3);
 const walkIn=walkInCustomer;
 draft={customerId:walkIn?String(walkIn.id):'',orderBy:walkIn?.name||'',phone:walkIn?.phone||'',whatsapp:walkIn?.phone||'',date:localISODate(),due:localISODate(dueDate),dueHour:'07',dueMinute:'30',dueMeridiem:'AM',discount:0,roundOff:0,roundOffEnabled:true,advance:0,paymentMode:'cash',paymentMethodId:defaultPaymentMethodId(),paymentReference:'',comment:'',sendWhatsapp:true,autoInvoice:true,items:{flex:[],digital:[],other:[]}};
 newJobStep=1;jobTab='flex';page='new-job';renderPage();
 if(walkIn)loadCustomerOutstanding(walkIn.id,{force:true});
 if(!walkInLoaded)loadWalkInCustomer();
}
function buildOrderItems(){
 const lines=[];
 for(const [category,items] of Object.entries(draft.items)){
  for(const item of items){
   const populated=Object.entries(item).some(([key,value])=>!['dimension_unit','rate_override','fabrication_rate_override'].includes(key)&&String(value??'').trim()!=='');
   if(!populated)continue;
   const qtyValue=String(item.qty??'').trim(),qty=Number(qtyValue);
   if(qtyValue===''||!Number.isFinite(qty)||qty<=0)throw new Error('Enter a quantity greater than zero for every job item.');
   const rateValue=String(item.rate??'').trim(),rate=rateValue===''?lineUnitRate(category,item):Number(rateValue);
   if(!Number.isFinite(rate)||rate<0)throw new Error('Select a priced master or enter a valid non-negative rate.');
   const rateOverride=Boolean(item.rate_override);
   let description='',unit='item',specifications={category};
   const quantity=round2(qty);
   if(category==='flex'){
    const media=jobcardMasterById('flex_media',item.media_id),fabrication=jobcardMasterById('fabrication',item.fabrication_id);
    if(!media||!media.is_active)throw new Error('Select an active Flex Media master.');
    if(fabrication&&!fabrication.is_active)throw new Error('Select an active Fabrication master or clear the selection.');
    const dimensionUnit=item.dimension_unit||jobcardSettings.default_flex_dimension_unit||'ft';
    const width=Number(item.w||0),height=Number(item.h||0),billingWidth=Number(item.bw||item.w||0),billingHeight=Number(item.bh||item.h||0);
    if(width<=0||height<=0||billingWidth<=0||billingHeight<=0)throw new Error('Enter physical and billing width and height for every Flex item.');
    const areaPerPiece=billingWidth*billingHeight*(dimensionUnit==='in'?1/144:1);
    if(round2(areaPerPiece*quantity)<=0)throw new Error('The billable Flex area must be greater than zero.');
    description=[media.name,fabrication?.name||''].filter(Boolean).join(' · ');unit='piece';
    specifications={category:'flex',media_id:Number(media.id),fabrication_id:fabrication?Number(fabrication.id):null,fabrication_rate_override:fabrication?Boolean(item.fabrication_rate_override):false,fabrication_rate:fabrication&&item.fabrication_rate_override?Number(item.fabrication_rate||0):null,dimension_unit:dimensionUnit,width:round2(width),height:round2(height),billing_width:round2(billingWidth),billing_height:round2(billingHeight),pieces:quantity,rate_override:rateOverride,remark:String(item.remark||'').trim()||null};
   }else if(category==='digital'){
    const particular=jobcardMasterById('digital_particular',item.particular_id),media=jobcardMasterById('digital_media',item.media_id),size=jobcardMasterById('digital_size',item.size_id),side=jobcardMasterById('digital_side',item.side_id);
    if(!particular?.is_active||!media?.is_active||!size?.is_active||!side?.is_active)throw new Error('Select active Particular, Media, Size and Side masters for every Digital/Paper item.');
    if(!matchedDigitalRate(item)&&!rateOverride)throw new Error('No price exists for this Particular + Media + Size + Side. Add the matrix rate or enter an allowed override.');
    description=[particular.name,media.name,size.name,side.name].join(' · ');unit=particular.unit||'piece';
    specifications={category:'digital',particular_id:Number(particular.id),media_id:Number(media.id),size_id:Number(size.id),side_id:Number(side.id),rate_override:rateOverride,remark:String(item.remark||'').trim()||null};
   }else{
    const master=jobcardMasterById('other_item',item.other_item_id);
    if(!master?.is_active)throw new Error('Select an active Other Item master.');
    description=[master.name,String(item.size||'').trim()].filter(Boolean).join(' · ');unit=master.unit||'item';
    specifications={category:'other',other_item_id:Number(master.id),size:String(item.size||'').trim()||null,rate_override:rateOverride,remark:String(item.remark||'').trim()||null};
   }
   lines.push({description:description.slice(0,180),quantity,unit,unit_price:round2(rate),specifications});
  }
 }
 return lines;
}
async function saveJob(){
 if(orderSaveInProgress)return;
 if(!canCreateOrders){toast('Your workspace role cannot create jobcards.');return}
 const customer=findJobCustomer(draft.customerId);
 if(!customer){toast('Select a customer before saving.');newJobStep=1;renderPage();return}
 if(!draft.date||!draft.due){toast('Enter both the job date and delivery date.');newJobStep=1;renderPage();return}
 if(draft.due<draft.date){toast('Delivery date cannot be earlier than the job date.');newJobStep=1;renderPage();return}
 let items;try{items=buildOrderItems()}catch(error){toast(error.message);newJobStep=2;renderPage();return}
 if(!items.length||draftSubtotal()<=0){toast('Add at least one priced job item before saving.');newJobStep=2;renderPage();return}
 const subtotal=round2(draftSubtotal()),discount=round2(draft.discount||0),roundOff=draft.roundOffEnabled?round2(draft.roundOff||0):0,advance=round2(draft.advance||0);
 const total=round2(subtotal-discount+roundOff);
 if(discount<0||discount>subtotal){toast('Discount must be zero or less than the items subtotal.');newJobStep=3;renderPage();return}
 if(total<=0){toast('The final job total must be greater than zero.');newJobStep=3;renderPage();return}
 if(advance<0||advance>total){toast('Advance cannot exceed the final bill.');newJobStep=3;renderPage();return}
 if(customer.is_default&&advance<total){toast(tr('Walk-In Customer bills must be paid in full. Create or select a named customer to leave a balance due.'));newJobStep=3;renderPage();return}
 if(advance>0&&(!draft.paymentMode||!draft.paymentMethodId)){ toast('Choose a payment mode and deposit account for the advance.');newJobStep=3;renderPage();return}
 const printType=items.some(item=>item.specifications.category==='flex')?'flex':items.some(item=>item.specifications.category==='digital')?'digital':'other';
 const title=items.map(item=>item.description).slice(0,3).join(' + ').slice(0,180);
 const payload={customer_id:Number(customer.id),job_date:draft.date,contact_name:String(draft.orderBy||customer.name).trim(),contact_phone:String(draft.phone||customer.phone||'').trim()||null,whatsapp_phone:String(draft.whatsapp||customer.phone||'').trim()||null,title,print_type:printType,description:null,quantity:1,unit:'job',items,discount,tax:0,round_off:roundOff,due_at:`${draft.due} ${dueTime24()}:00`,notes:String(draft.comment||'').trim()||null,priority:'normal',auto_invoice:true,advance_amount:advance,payment_method:advance>0?draft.paymentMode:null,payment_method_id:advance>0?Number(draft.paymentMethodId):null,payment_reference:String(draft.paymentReference||'').trim()||null};
 let jobSheetWindow=null;
 try{
  jobSheetWindow=window.open('about:blank','_blank');
  if(jobSheetWindow){jobSheetWindow.document.open();jobSheetWindow.document.write('<!doctype html><title>Preparing Job Card</title><body style="font-family:Arial,sans-serif;padding:24px;color:#26364a">Jobcard saved. Preparing the print card…</body>');jobSheetWindow.document.close()}
 }catch(error){jobSheetWindow=null}
 orderSaveInProgress=true;
 const saveButton=$('[data-action="save-job"]');if(saveButton){saveButton.disabled=true;saveButton.textContent='Saving…'}
 try{
  const saved=await apiRequest('/api/v1/orders',{method:'POST',body:JSON.stringify(payload)});
  if(jobSheetWindow&&!jobSheetWindow.closed)jobSheetWindow.location.href=`/orders/${encodeURIComponent(saved.id)}/job-sheet?autoprint=1`;
  orderSaveInProgress=false;ordersLoaded=false;ordersSearch='';ordersStatus='';ordersCurrentPage=1;page='job-cards';
  loadOrders({force:true,quiet:true,pageNumber:1,search:'',status:''});loadDashboardSummary({force:true,quiet:true});renderPage();
  const invoice=saved.invoices?.[0],payment=invoice?.payments?.[0];
  let message=`Jobcard ${saved.job_number} saved.`;
  if(invoice)message+=` Invoice ${invoice.invoice_number} generated.`;
  if(payment)message+=` Receipt ${payment.receipt_number||`RCP-${String(payment.id).padStart(6,'0')}`} recorded.`;
  if(jobSheetWindow&&!jobSheetWindow.closed)message+=' Job Card opened for printing.';
  else message+=' Use Print Job Card in jobcard details if the browser blocked the popup.';
  if(draft.sendWhatsapp)message+=' WhatsApp was not sent (integration not configured).';
  toast(message);
 }catch(error){if(jobSheetWindow&&!jobSheetWindow.closed)jobSheetWindow.close();orderSaveInProgress=false;toast(error.message);renderPage()}
}
function customerSearchFilter(input){const val=input.value.toLowerCase();const rows=$$('#genericTable tbody tr');rows.forEach(row=>row.style.display=row.textContent.toLowerCase().includes(val)?'':'none')}
function $$(selector,root=document){return Array.from(root.querySelectorAll(selector))}
function addItem(){const item={};if(jobTab==='flex')item.dimension_unit=jobcardSettings.default_flex_dimension_unit||'ft';draft.items[jobTab].push(item);renderPage()}
function updateDraftField(target){const key=target.dataset.draft;if(!key)return;if(target.type==='checkbox')draft[key]=target.checked;else draft[key]=target.value;if(key==='customerId'){const c=findJobCustomer(draft.customerId);draft.orderBy=c?.name||'';draft.phone=c?.phone||'';draft.whatsapp=c?.whatsapp||'';draft.advance=c?.is_default?round2(finalBill()):0;renderPage();if(c?.id)loadCustomerOutstanding(c.id,{force:true});return}if(key==='roundOffEnabled'){const roundOffInput=$('[data-draft="roundOff"]');if(roundOffInput)roundOffInput.disabled=!draft.roundOffEnabled}if(['discount','roundOff','roundOffEnabled','advance'].includes(key))updateBillingNumbers()}
function updateLineField(target){
 const cat=target.dataset.line,index=Number(target.dataset.index),field=target.dataset.field;
 if(!cat||!field||!draft.items[cat][index])return;
 const item=draft.items[cat][index];
 item[field]=target.value;
 if(cat==='flex'&&field==='w'){
  item.bw=target.value;
  const billingInput=target.closest('tr')?.querySelector('[data-field="bw"]');
  if(billingInput)billingInput.value=target.value;
 }
 if(cat==='flex'&&field==='h'){
  item.bh=target.value;
  const billingInput=target.closest('tr')?.querySelector('[data-field="bh"]');
  if(billingInput)billingInput.value=target.value;
 }
 if(field==='rate')item.rate_override=true;
 if(field==='fabrication_rate')item.fabrication_rate_override=true;
 const rateChanged=(cat==='flex'&&field==='media_id')||(cat==='other'&&field==='other_item_id')||(cat==='digital'&&['particular_id','media_id','size_id','side_id'].includes(field));
 if(rateChanged){
  let rate='';
  if(cat==='flex')rate=jobcardMasterById('flex_media',item.media_id)?.rate??'';
  if(cat==='other')rate=jobcardMasterById('other_item',item.other_item_id)?.rate??'';
  if(cat==='digital')rate=matchedDigitalRate(item)?.rate??'';
  item.rate=rate;item.rate_override=false;
  const rateInput=target.closest('tr')?.querySelector('[data-field="rate"]');if(rateInput)rateInput.value=rate;
 }
 if(cat==='flex'&&field==='fabrication_id'){
  item.fabrication_rate=jobcardMasterById('fabrication',item.fabrication_id)?.rate??'';item.fabrication_rate_override=false;
  const fabricationInput=target.closest('tr')?.querySelector('[data-field="fabrication_rate"]');if(fabricationInput)fabricationInput.value=item.fabrication_rate;
 }
 const row=target.closest('tr'),calc=lineTotal(cat,item),area=row?.querySelector('[data-calc="area"]'),total=row?.querySelector('[data-calc="total"]');
 if(area)area.textContent=calc.area.toFixed(2);
 if(total)total.textContent=money(calc.total);
 refreshItemTotals();
}
function attendanceTab(name){toast(name+' view selected.');}
function genericAdd(){openModal(`<div class="modal-head"><div><h3>Add ${esc(pageName(page).replace(/s$/,''))}</h3><p>Quick-create form for this preview.</p></div><button class="close" data-action="close-modal">×</button></div><div class="modal-body"><div class="field"><label>Name / reference *</label><input class="input" id="genericName" placeholder="Enter a name"></div><div class="field" style="margin-top:10px"><label>Notes</label><textarea class="textarea" placeholder="Optional details"></textarea></div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-generic">Save</button></div>`)}
function taxModal(kind){if(kind==='rate'){openModal(`<div class="modal-head"><div><h3>New Tax Rate</h3><p>Create one reusable rate for this business; apply it through a tax group.</p></div><button class="close" data-action="close-modal">×</button></div><form id="taxForm" data-kind="rate"><div class="modal-body"><div class="settings-form"><div class="field"><label>Tax name *</label><input class="input" name="name" required placeholder="e.g. VAT"></div><div class="field"><label>Code *</label><input class="input" name="code" required placeholder="e.g. VAT18"></div><div class="field"><label>Calculation type</label><select class="select" name="calculation_type"><option value="percentage">Percentage</option><option value="fixed">Fixed amount per unit</option></select></div><div class="field"><label>Rate *</label><input class="input" type="number" name="rate" min="0" step="0.0001" required placeholder="18.0000"></div><div class="field"><label>Valid from</label><input class="input" type="date" name="valid_from"></div><div class="field"><label>Valid until</label><input class="input" type="date" name="valid_until"></div><div class="field full"><label><input type="checkbox" name="is_compound"> Compound tax (this rate applies after earlier rates)</label></div></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Save tax rate</button></div></form>`);return}openModal(`<div class="modal-head"><div><h3>New Tax Group</h3><p>Combine tax rates and choose inclusive or exclusive pricing.</p></div><button class="close" data-action="close-modal">×</button></div><form id="taxForm" data-kind="group"><div class="modal-body"><div class="settings-form"><div class="field"><label>Group name *</label><input class="input" name="name" required placeholder="Standard VAT"></div><div class="field"><label>Code *</label><input class="input" name="code" required placeholder="STD-VAT"></div><div class="field full"><label>Included tax rates *</label><div class="tax-rate-checks">${taxRates.filter(r=>r.is_active).map(r=>`<label><input type="checkbox" name="tax_rate_ids" value="${r.id}"> ${esc(r.name)} · ${r.calculation_type==='percentage'?`${r.rate}%`:`LKR ${r.rate}`}</label>`).join('')}</div></div><div class="field full"><label><input type="checkbox" name="is_inclusive"> Product prices already include this tax</label></div><div class="field full"><label>Description</label><textarea class="textarea" name="description" placeholder="Optional"></textarea></div></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Save tax group</button></div></form>`)}
function taxPreviewDemo(){const group=taxGroups.find(g=>String(g.id)===$('#taxPreviewGroup')?.value),amount=Number($('#taxPreviewAmount')?.value||0),qty=Number($('#taxPreviewQty')?.value||1);if(!group||amount<0||qty<=0){toast('Choose a group and valid amount/quantity.');return}const rates=group.rateIds.map(id=>taxRates.find(r=>r.id===id)).filter(r=>r&&r.is_active);const partsFor=base=>{let running=base;const parts=rates.map(r=>{const v=r.calculation_type==='fixed'?Number(r.rate)*qty:(r.is_compound?running:base)*Number(r.rate)/100;if(r.is_compound)running+=v;return {name:r.name,amount:v}});return parts};let taxable=amount,parts=partsFor(amount);if(group.is_inclusive){let low=0,high=amount;for(let i=0;i<60;i++){const mid=(low+high)/2;if(mid+partsFor(mid).reduce((a,p)=>a+p.amount,0)>amount)high=mid;else low=mid}taxable=Math.round(((low+high)/2)*100)/100;parts=partsFor(taxable);const totalTax=Math.round((amount-taxable)*100)/100;let diff=Math.round((totalTax-parts.reduce((a,p)=>a+Math.round(p.amount*100)/100,0))*100)/100;if(parts.length)parts[parts.length-1].amount=Math.round((Math.round(parts[parts.length-1].amount*100)/100+diff)*100)/100}else parts=parts.map(p=>({...p,amount:Math.round(p.amount*100)/100}));const tax=group.is_inclusive?Math.round((amount-taxable)*100)/100:parts.reduce((a,p)=>a+p.amount,0),total=group.is_inclusive?amount:taxable+tax;$('#taxPreviewResult').innerHTML=`<strong>Calculated amount</strong><div class="tax-result-row"><span>Taxable amount</span><b>${money(taxable)}</b></div>${parts.map(p=>`<div class="tax-result-row"><span>${esc(p.name)}</span><b>${money(p.amount)}</b></div>`).join('')}<div class="tax-result-row tax-result-total"><span>Tax total</span><b>${money(tax)}</b></div><div class="tax-result-row tax-result-total"><span>Invoice total</span><b>${money(total)}</b></div><small>Preview only · Laravel recalculates and snapshots tax at finalization.</small>`}
function currentCustomersPage(){page='customers';renderPage()}
function renderAccountingPage(id){return accountingPage(id)}
function init(){const languageSelect=$('#language');if(languageSelect)languageSelect.value=lang;renderPage();loadCustomers({quiet:true})}

document.addEventListener('click',e=>{
 const pageBtn=e.target.closest('[data-page]');if(pageBtn){const target=pageBtn.dataset.page;if(JOBCARD_MASTER_PAGE_MAP[target]){jobcardMasterTab=JOBCARD_MASTER_PAGE_MAP[target];page='jobcard-masters'}else page=target;tableQuery='';if(page==='job-status'){ordersCurrentPage=1;ordersSearch='';ordersStatus='';ordersLoaded=false}renderPage();$('#sidebar').classList.remove('open');return}
 const itemTab=e.target.closest('[data-item-tab]');if(itemTab){jobTab=itemTab.dataset.itemTab;renderPage();return}
 const masterTab=e.target.closest('[data-jobcard-master-tab]');if(masterTab){jobcardMasterTab=masterTab.dataset.jobcardMasterTab;renderPage();return}
  const taxSwitch=e.target.closest('[data-tax-tab]');if(taxSwitch){taxTab=taxSwitch.dataset.taxTab;renderPage();return}
  const setting=e.target.closest('[data-setting-tab]');if(setting){settingsTab=setting.dataset.settingTab;renderPage();return}
 const att=e.target.closest('[data-att-tab]');if(att){$$('[data-att-tab]').forEach(x=>x.classList.toggle('active',x===att));attendanceTab(att.dataset.attTab);return}
 const report=e.target.closest('[data-report]');if(report){toast(report.dataset.report+' report selected.');return}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='show-payment-receipts'){const orderId=e.target.closest('[data-action="show-payment-receipts"]')?.dataset.orderId;showPaymentReceipts(orderId);return}
 if(action==='refresh-jobcard-masters'){jobcardMastersLoaded=false;loadJobcardMasters({force:true});return}if(action==='refresh-jobcard-settings'){businessSettingsLoaded=false;loadBusinessSettings({force:true});return}if(action==='jobcard-master-add'){if(!canManageJobcardMasters){toast('Only workspace owners or managers can edit jobcard masters.');return}jobcardMasterModal(jobcardMasterTab);return}if(action==='edit-jobcard-master'){if(!canManageJobcardMasters)return;const button=e.target.closest('[data-action="edit-jobcard-master"]');jobcardMasterModal(button?.dataset.type,button?.dataset.id);return}if(action==='edit-jobcard-rate'){if(!canManageJobcardMasters)return;const button=e.target.closest('[data-action="edit-jobcard-rate"]');jobcardMasterModal('digital_rates',button?.dataset.id);return}
 if(action==='refresh-customers'){customersLoaded=false;customersError='';loadCustomers({force:true});if(page==='new-job'){walkInLoaded=false;walkInError='';loadWalkInCustomer()}return}if(action==='refresh-customer-outstanding'){const button=e.target.closest('[data-action="refresh-customer-outstanding"]');loadCustomerOutstanding(button?.dataset.customerId,{force:true});return}if(action==='refresh-orders'){loadOrders({force:true,pageNumber:ordersCurrentPage,search:ordersSearch,status:ordersStatus});return}if(action==='refresh-dashboard'){loadDashboardSummary({force:true});loadOrders({force:true,pageNumber:1,search:'',status:''});return}if(action==='apply-order-filters'){const search=$('[data-page-search]')?.value.trim()||'',status=$('[data-order-status]')?.value||'';loadOrders({force:true,pageNumber:1,search,status});return}if(action==='orders-page'){const number=Number(e.target.closest('[data-action="orders-page"]')?.dataset.pageNumber||1);loadOrders({force:true,pageNumber:number});return}if(action==='move-stage'){const button=e.target.closest('[data-action="move-stage"]'),scope=button?.closest('.job-mini')||$('#modal'),stage=scope?.querySelector('[data-stage-select]')?.value||'',note=scope?.querySelector('[data-stage-note]')?.value.trim()||'';moveOrderStage(button?.dataset.orderId,stage,note);return}if(action==='view-order'){showOrderDetails(e.target.closest('[data-action="view-order"]')?.dataset.orderId);return}if(action==='new-job'){startJob();return}if(action==='quick-payment'){transactionModal('payment');return}if(action==='quick-receipt'){transactionModal('receipt');return}if(action==='close-modal'){closeModal();return}if(action==='add-customer'){customerModal();return}if(action==='job-next'){if(newJobStep===1&&!draft.customerId){toast('Select a customer to continue.');return}newJobStep=Math.min(3,newJobStep+1);renderPage();return}if(action==='job-prev'){newJobStep=Math.max(1,newJobStep-1);renderPage();return}if(action==='cancel-job'){if(confirm('Discard this jobcard?')){page='dashboard';renderPage()}return}if(action==='add-item'){addItem();return}if(action==='remove-item'){draft.items[e.target.closest('[data-category]')?.dataset.category||e.target.dataset.category].splice(Number(e.target.dataset.index),1);renderPage();return}if(action==='save-job'){saveJob();return}
 if(action==='tax-add-rate'){taxModal('rate');return}if(action==='tax-add-group'){taxModal('group');return}if(action==='tax-calc'){taxPreviewDemo();return}if(action==='save-settings'){if(settingsTab==='Jobcards'){saveJobcardSettings();return}toast('Settings saved in this preview only.');return}if(action==='generic-add'){genericAdd();return}if(action==='save-generic'){closeModal();toast('Saved in the preview only.');return}if(action==='export'){toast('Export action will be connected to Laravel reporting.');return}if(action==='print'){window.print();return}if(action==='filter'){toast('Filters applied to the preview.');return}if(action==='import'){toast('Choose a CSV/XLS file when the import workflow is connected.');return}if(action==='add-task'){toast('Task added to the follow-up queue (preview).');return}if(action==='row-menu'){const rowButton=e.target.closest('[data-action="row-menu"]');if(page==='customers'&&rowButton?.dataset.rowId){customerModal(Number(rowButton.dataset.rowId));return}if((ORDER_DATA_PAGES.has(page)||page==='dashboard')&&rowButton?.dataset.rowId){showOrderDetails(Number(rowButton.dataset.rowId));return}toast('Record actions: View · Edit · Print');return}
});
document.addEventListener('input',e=>{if(e.target.dataset.draft!==undefined)updateDraftField(e.target);if(e.target.dataset.line!==undefined)updateLineField(e.target);if(e.target.dataset.pageSearch!==undefined){const q=e.target.value.toLowerCase();$$('#genericTable tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}if(e.target.dataset.boardSearch!==undefined){const q=e.target.value.toLowerCase();$$('.job-mini').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}});
document.addEventListener('change',e=>{if(e.target.id==='language'){lang=e.target.value;renderPage();toast('Language preview changed.');return}if(e.target.dataset.draft!==undefined)updateDraftField(e.target);if(e.target.dataset.line!==undefined)updateLineField(e.target)});
document.addEventListener('submit',async e=>{if(e.target.id!=='jobcardMasterForm')return;e.preventDefault();const form=e.target,fd=new FormData(form),kind=form.dataset.kind,recordId=form.dataset.id,editing=Boolean(recordId);let payload,endpoint,method;if(kind==='digital_rate'){payload={particular_id:Number(fd.get('particular_id')),media_id:Number(fd.get('media_id')),size_id:Number(fd.get('size_id')),side_id:Number(fd.get('side_id')),rate:Number(fd.get('rate')),is_active:editing?fd.has('is_active'):true};endpoint=editing?`/api/v1/jobcard-masters/digital-rates/${encodeURIComponent(recordId)}`:'/api/v1/jobcard-masters/digital-rates';method=editing?'PATCH':'POST'}else{const type=form.dataset.type;payload={type,name:String(fd.get('name')||'').trim(),code:String(fd.get('code')||'').trim()||null,unit:fd.get('unit')?String(fd.get('unit')):null,rate:fd.get('rate')===''?null:Number(fd.get('rate')),charge_mode:fd.get('charge_mode')?String(fd.get('charge_mode')):null,is_active:editing?fd.has('is_active'):true};endpoint=editing?`/api/v1/jobcard-masters/${encodeURIComponent(recordId)}`:'/api/v1/jobcard-masters';method=editing?'PATCH':'POST'}try{await apiRequest(endpoint,{method,body:JSON.stringify(payload)});closeModal();jobcardMastersLoaded=false;await loadJobcardMasters({force:true,quiet:true});toast('Jobcard master saved to this workspace.')}catch(error){const box=$('#jobcardMasterErrors');if(box){box.textContent=error.message;box.style.display='block'}else toast(error.message)}return});
document.addEventListener('submit',async e=>{if(e.target.id==='customerForm'){e.preventDefault();const form=e.target,fd=new FormData(form),kind=String(fd.get('type')||'customer'),customerId=form.dataset.customerId;const creditValue=String(fd.get('credit_limit')||'').trim();const payload={name:String(fd.get('name')||'').trim(),contact_code:String(fd.get('contact_code')||'').trim()||null,phone:String(fd.get('phone')||'').trim()||null,email:String(fd.get('email')||'').trim()||null,billing_address:String(fd.get('billing_address')||'').trim()||null,notes:String(fd.get('notes')||'').trim()||null,payment_term_days:Number(fd.get('payment_term_days')||0),is_customer:kind==='customer'||kind==='both',is_supplier:kind==='supplier'||kind==='both'};if(creditValue!=='')payload.credit_limit=Number(creditValue);else if(customerId)payload.credit_limit=null;try{const saved=await apiRequest(customerId?`/api/v1/customers/${encodeURIComponent(customerId)}`:'/api/v1/customers',{method:customerId?'PATCH':'POST',body:JSON.stringify(payload)});const contact=normalizeCustomer(saved);customers=customers.filter(c=>String(c.id)!==String(contact.id));customers.push(contact);customers.sort((a,b)=>a.name.localeCompare(b.name));customersLoaded=true;customersError='';if(!customerId)customerTotal++;if(page==='new-job'){draft.customerId=contact.id;draft.orderBy=contact.name;draft.phone=contact.phone;draft.whatsapp=contact.phone;draft.advance=0}closeModal();renderPage();if(page==='new-job'&&draft.customerId)loadCustomerOutstanding(contact.id,{force:true});toast(customerId?'Contact updated.':'Contact saved to the workspace.')}catch(error){const box=$('#customerFormErrors');if(box){box.textContent=error.message;box.style.display='block'}else toast(error.message)}return}if(e.target.id==='transactionForm'){e.preventDefault();const fd=new FormData(e.target),kind=e.target.dataset.kind,amount=Number(fd.get('amount')||0),date=new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});if(kind==='receipt')receipts.unshift({ref:'REC-'+String(641+receipts.length).padStart(5,'0'),date,customer:String(fd.get('party')),invoice:String(fd.get('reference')||'—'),amount,mode:String(fd.get('mode'))});else payments.unshift({ref:'PAY-'+String(1085+payments.length).padStart(5,'0'),date,payee:String(fd.get('party')),amount,mode:String(fd.get('mode')),remark:String(fd.get('note')||fd.get('reference')||'—'),user:'Demo User'});closeModal();renderPage();toast((kind==='receipt'?'Receipt':'Payment')+' saved in the demo preview.')}});
document.addEventListener('submit',e=>{if(e.target.id!=='taxForm')return;e.preventDefault();const fd=new FormData(e.target),kind=e.target.dataset.kind,code=String(fd.get('code')||'').trim().toUpperCase(),name=String(fd.get('name')||'').trim();if(kind==='rate'){if(taxRates.some(r=>r.code.toUpperCase()===code)){toast('That tax code already exists in this demo.');return}taxRates.push({id:Date.now(),code,name,calculation_type:String(fd.get('calculation_type')),rate:Number(fd.get('rate')||0),is_compound:fd.has('is_compound'),valid_from:String(fd.get('valid_from')||''),valid_until:String(fd.get('valid_until')||''),is_active:true});closeModal();renderPage();toast('Tax rate saved in this preview only.');return}const rateIds=fd.getAll('tax_rate_ids').map(Number);if(!rateIds.length){toast('Choose at least one tax rate.');return}if(taxGroups.some(g=>g.code.toUpperCase()===code)){toast('That tax group code already exists in this demo.');return}taxGroups.push({id:Date.now(),code,name,is_inclusive:fd.has('is_inclusive'),is_active:true,rateIds});closeModal();renderPage();toast('Tax group saved in this preview only.')});
$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#backdrop').addEventListener('click',e=>{if(e.target.id==='backdrop')closeModal()});$('#alerts').addEventListener('click',()=>toast('You are all caught up.'));$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){tableQuery=e.target.value.trim();page='job-cards';loadOrders({force:true,pageNumber:1,search:tableQuery,status:''});renderPage()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.dataset.pageSearch!==undefined&&ORDER_DATA_PAGES.has(page)){e.preventDefault();loadOrders({force:true,pageNumber:1,search:e.target.value.trim(),status:$('[data-order-status]')?.value||''})}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}});
init();
</script>
